/* CNC machining - chapter quiz bank.
   Converted from "CNC Chapt. Questions.docx" (Trades Question Bank). One entry per
   chapter; q = the question and a = the book answer, both as written in the book. */
registerChapters("cnc", [
{ id: "c1-0", no: "1.0", title: "સલામતી નો પરિચય (Introduction to Safety)", qs: [
  { q: "સલામતી શું છે?", a: "અકસ્માત, ઈજા અને નુકસાનથી બચવા માટે પહેલેથી લેવાતી કાળજીને સલામતી કહે છે." },
  { q: "સલામતીનું મુખ્ય મહત્વ શું છે?", a: "માનવજીવનનું રક્ષણ કરવું અને ઈજા તથા જાનહાનિ અટકાવવી." },
  { q: "PPE નું સંપૂર્ણ નામ શું છે?", a: "Personal Protective Equipment." },
  { q: "PPE શા માટે ઉપયોગી છે?", a: "કાર્ય દરમિયાન થતા જોખમો અને ઈજાઓથી વ્યક્તિનું રક્ષણ કરવા માટે." },
  { q: "હેલ્મેટ શા માટે પહેરવામાં આવે છે?", a: "માથાને પડતી વસ્તુઓ, ધક્કા અને ટક્કરથી બચાવવા માટે." },
  { q: "સેફ્ટી ગોગલ્સનો ઉપયોગ શા માટે થાય છે?", a: "આંખોને ધૂળ, ધુમાડો, કેમિકલ અને સ્પાર્કથી બચાવવા માટે." },
  { q: "ઇયરપ્લગ અથવા ઇયરમફનો ઉપયોગ શા માટે થાય છે?", a: "વધુ અવાજથી કાનનું રક્ષણ કરવા માટે." },
  { q: "ગ્લોવ્સ શા માટે પહેરવામાં આવે છે?", a: "હાથને ગરમી, કટ, કેમિકલ અને ઈજાથી બચાવવા માટે." },
  { q: "સેફ્ટી શૂઝનો મુખ્ય ઉપયોગ શું છે?", a: "પગને ભારે વસ્તુ પડવાથી અને તીક્ષ્ણ વસ્તુઓથી બચાવવા માટે." },
  { q: "CNC મશીન પર કામ કરતી વખતે ઢીલા કપડાં શા માટે ન પહેરવા જોઈએ?", a: "ઢીલા કપડાં ફરતા ભાગમાં ફસાઈને અકસ્માત કરી શકે છે." },
  { q: "CNC મશીન ચાલુ કરતાં પહેલાં શું તપાસવું જોઈએ?", a: "વર્કપીસ યોગ્ય રીતે ક્લેમ્પ થયેલ છે કે નહીં તે તપાસવું જોઈએ." },
  { q: "ટૂલ ફિટિંગ વખતે શું તપાસવું જોઈએ?", a: "ટૂલ યોગ્ય રીતે ફિટ છે અને ટૂલ નંબર તથા ઓફસેટ સાચા છે કે નહીં તે તપાસવું જોઈએ." },
  { q: "Single Block મોડનો ઉપયોગ શા માટે થાય છે?", a: "CNC પ્રોગ્રામને એક-એક બ્લોક ચલાવીને સલામત રીતે ચકાસવા માટે." },
  { q: "CNC મશીનમાં ચિપ્સ કેવી રીતે દૂર કરવી જોઈએ?", a: "બ્રશ અથવા ચિપ હૂકનો ઉપયોગ કરીને દૂર કરવી જોઈએ." },
  { q: "મશીનમાંથી અસામાન્ય અવાજ આવે તો શું કરવું?", a: "તરત મશીન બંધ કરીને સુપરવાઈઝરને જાણ કરવી." },
  { q: "મશીનના ગાર્ડ અથવા ઇન્ટરલોક કેમ દૂર ન કરવા જોઈએ?", a: "અકસ્માત અને ઈજાથી બચવા માટે સુરક્ષા ઉપકરણો દૂર ન કરવા જોઈએ." },
  { q: "Water Fire Extinguisher કઈ આગ માટે ઉપયોગી છે?", a: "લાકડું, કાપડ અને કાગળ જેવી સામાન્ય આગ માટે." },
  { q: "CO₂ Fire Extinguisher કઈ આગ માટે ઉપયોગી છે?", a: "મુખ્યત્વે ઇલેક્ટ્રિકલ આગ માટે." },
  { q: "Wet Chemical Extinguisher ક્યાં ઉપયોગ થાય છે?", a: "રસોડામાં તેલથી લાગેલી આગ માટે." },
  { q: "5S પદ્ધતિ શું છે?", a: "કાર્યસ્થળને સ્વચ્છ, ગોઠવેલ, સલામત અને કાર્યક્ષમ બનાવવાની પદ્ધતિ છે." },
  { q: "5S માં Seiri નો અર્થ શું છે?", a: "જરૂરી અને અનાવશ્યક વસ્તુઓની છાંટણી કરવી." },
  { q: "Seiton નો અર્થ શું છે?", a: "જરૂરી વસ્તુઓને યોગ્ય અને નક્કી કરેલી જગ્યાએ ગોઠવવી." },
  { q: "Seiso નો અર્થ શું છે?", a: "કાર્યસ્થળ, મશીન અને સાધનોની નિયમિત સફાઈ કરવી." },
  { q: "Seiketsu નો અર્થ શું છે?", a: "કાર્યસ્થળની વ્યવસ્થા અને સફાઈ માટે નિયમો તથા ધોરણો બનાવવું." },
  { q: "Shitsuke નો અર્થ શું છે?", a: "બનાવેલા નિયમોનું નિયમિત પાલન કરીને શિસ્ત જાળવવી." }
]},
{ id: "c2-1", no: "2.1", title: "મૂળભૂત રેખીય માપન (Basic Linear Measurement)", qs: [
  { q: "માપનું શું મહત્વ છે?", a: "જોબને જરૂરી સાઈઝ અને આકારમાં ચોકસાઈથી બનાવવા માટે માપનું મહત્વ છે." },
  { q: "ખોટું માપ લેવાથી શું નુકસાન થઈ શકે?", a: "જોબ રિજેક્ટ થઈ શકે છે અને સમય તથા ખર્ચ વધી શકે છે." },
  { q: "લિનિયર માપ એટલે શું?", a: "સીધી રેખામાં લેવામાં આવતા માપને લિનિયર માપ કહે છે." },
  { q: "લિનિયર માપમાં કયા માપ લેવામાં આવે છે?", a: "લંબાઈ, પહોળાઈ, ઊંચાઈ અને વ્યાસ જેવા માપ લેવામાં આવે છે." },
  { q: "લિનિયર માપ લેવા માટે કયા સાધનો વપરાય છે?", a: "સ્ટીલ રૂલ, કેલિપર, માઇક્રોમીટર અને વર્નિયર કેલિપર વપરાય છે." },
  { q: "એંગ્યુલર માપ એટલે શું?", a: "બે સીધી રેખાઓ એકબીજાને ક્રોસ કરતાં બનેલા કોણનું માપ એંગ્યુલર માપ કહેવાય છે." },
  { q: "એંગ્યુલર માપ માટે કયા સાધનો વપરાય છે?", a: "એંગલ પ્રોટેક્ટર, વર્નિયર બેવલ પ્રોટેક્ટર અને સાઈન બાર જેવા સાધનો વપરાય છે." },
  { q: "રેડિયસ માપ એટલે શું?", a: "ગોળાકાર અથવા વક્ર સપાટીની ગોળાઈનું માપ રેડિયસ માપ કહેવાય છે." },
  { q: "રેડિયસ માપ માટે કયું સાધન વપરાય છે?", a: "રેડિયસ ગેજનો ઉપયોગ થાય છે." },
  { q: "પ્લેઈન સપાટીનું માપ શા માટે લેવામાં આવે છે?", a: "જોબની સપાટી સમતલ છે કે નહીં તે ચકાસવા માટે." },
  { q: "પ્લેઈન સપાટી ચકાસવા માટે કયા સાધનો વપરાય છે?", a: "સ્ટ્રેઇટ ગેજ, સરફેસ ગેજ અને ડાયલ ટેસ્ટ ઇન્ડિકેટર વપરાય છે." },
  { q: "F.P.S. નું સંપૂર્ણ નામ શું છે?", a: "Foot–Pound–Second." },
  { q: "F.P.S. સિસ્ટમમાં લંબાઈનું મુખ્ય યુનિટ શું છે?", a: "ફૂટ (Foot)." },
  { q: "મેટ્રિક સિસ્ટમમાં લંબાઈનું મુખ્ય યુનિટ શું છે?", a: "મીટર (Meter)." },
  { q: "S.I. નું સંપૂર્ણ નામ શું છે?", a: "System International." },
  { q: "S.I. સિસ્ટમ કયા સિદ્ધાંત પર આધારિત છે?", a: "S.I. સિસ્ટમ ડેસિમલ એટલે કે દશાંશ પદ્ધતિ પર આધારિત છે." },
  { q: "1 મીટરમાં કેટલા સેન્ટિમીટર હોય છે?", a: "1 મીટર = 100 સેન્ટિમીટર." },
  { q: "1 મીટરમાં કેટલા મિલીમીટર હોય છે?", a: "1 મીટર = 1000 મિલીમીટર." },
  { q: "1 મિલીમીટરમાં કેટલા માઇક્રોન હોય છે?", a: "1 મિલીમીટર = 1000 માઇક્રોન." },
  { q: "1 ઇંચ કેટલા મિલીમીટર બરાબર છે?", a: "1 ઇંચ = 25.4 mm." },
  { q: "1 યાર્ડ કેટલા ફૂટ બરાબર છે?", a: "1 યાર્ડ = 3 ફૂટ." },
  { q: "પ્રિસિઝન મેઝરમેન્ટ એટલે શું?", a: "ખૂબ ઊંચી ચોકસાઈ સાથે લેવામાં આવતા માપને પ્રિસિઝન મેઝરમેન્ટ કહે છે." },
  { q: "પ્રિસિઝન મેઝરમેન્ટ માટે કયા સાધનો વપરાય છે?", a: "માઇક્રોમીટર, વર્નિયર કેલિપર અને ડેપ્થ માઇક્રોમીટર વપરાય છે." },
  { q: "નોન-પ્રિસિઝન મેઝરમેન્ટ એટલે શું?", a: "જેમાં ખૂબ વધારે ચોકસાઈની જરૂર ન હોય તેવા માપને નોન-પ્રિસિઝન મેઝરમેન્ટ કહે છે." },
  { q: "પ્રિસિઝન અને નોન-પ્રિસિઝન મેઝરમેન્ટમાં મુખ્ય તફાવત શું છે?", a: "પ્રિસિઝન મેઝરમેન્ટમાં ચોકસાઈ વધારે હોય છે, જ્યારે નોન-પ્રિસિઝન મેઝરમેન્ટમાં ચોકસાઈ ઓછી હોય છે." }
]},
{ id: "c2-4", no: "2.4", title: "સ્ટીલ રૂલ અને યુનિટ કન્વર્ઝન (Steel Rule & Unit Conversion)", qs: [
  { q: "સ્ટીલ રૂલને સામાન્ય રીતે શું કહેવામાં આવે છે?", a: "સ્ટીલ રૂલને સામાન્ય રીતે સ્કેલ કહેવામાં આવે છે." },
  { q: "સ્ટીલ રૂલ કેવા પ્રકારનું મેઝરિંગ ઈન્સ્ટ્રુમેન્ટ છે?", a: "સ્ટીલ રૂલ નોન-પ્રિસિઝન ડાયરેક્ટ લાઈન મેઝરિંગ ઈન્સ્ટ્રુમેન્ટ છે." },
  { q: "સ્ટીલ રૂલ કઈ ધાતુમાંથી બને છે?", a: "સ્ટીલ રૂલ હાર્ડન કરેલા સ્ટીલની પાતળી પટ્ટીમાંથી બને છે." },
  { q: "સ્ટીલ રૂલ પર શું કોતરેલું હોય છે?", a: "તેના પર નિશ્ચિત અંતરે ગ્રેજ્યુએશન (Graduations) કોતરેલા હોય છે." },
  { q: "સ્ટીલ રૂલથી માપ કેવી રીતે વાંચવામાં આવે છે?", a: "લંબાઈનું માપ સીધું ગ્રેજ્યુએશન પરથી વાંચવામાં આવે છે." },
  { q: "સ્ટીલ રૂલનો ઉપયોગ શા માટે થાય છે?", a: "વર્કપીસની લંબાઈ જેવા સામાન્ય માપ લેવા માટે થાય છે." },
  { q: "સ્ટીલ રૂલની વિવિધ વેરાયટીઓનાં ઉદાહરણ કયા છે?", a: "ફોલ્ડેડ સ્કેલ અને મેઝર ટેપ તેના ઉદાહરણ છે." },
  { q: "સ્ટીલ રૂલથી સામાન્ય રીતે માપ કેવી રીતે લેવામાં આવે છે?", a: "સ્ટીલ રૂલને વર્કપીસ પર લગાડીને માપ લેવામાં આવે છે." },
  { q: "વધુ ચોકસાઈ માટે કઈ પદ્ધતિનો ઉપયોગ થાય છે?", a: "કોમન ડેટમ પદ્ધતિનો ઉપયોગ થાય છે." },
  { q: "કોમન ડેટમ પદ્ધતિમાં કોને કોમન ડેટમ તરીકે લેવામાં આવે છે?", a: "સરફેસ પ્લેટને કોમન ડેટમ તરીકે લેવામાં આવે છે." },
  { q: "સ્ટીલ રૂલ અને વર્કપીસને સરફેસ પ્લેટ પર કેવી રીતે રાખવામાં આવે છે?", a: "બંનેને સરફેસ પ્લેટ પર કાટખૂણે રાખીને માપ લેવામાં આવે છે." },
  { q: "સ્ટીલ રૂલ સિવાયના નોન-પ્રિસિઝન ડાયરેક્ટ મેઝરિંગ ઈન્સ્ટ્રુમેન્ટ કયા છે?", a: "સાદો મીટર અને ડેપ્થ ગેજ." },
  { q: "યુનિટ કન્વર્ઝન એટલે શું?", a: "કોઈ માપને એક યુનિટમાંથી બીજા યુનિટમાં ફેરવવાની પ્રક્રિયાને યુનિટ કન્વર્ઝન કહે છે." },
  { q: "વર્કશોપ અને CNC કાર્યમાં યુનિટ કન્વર્ઝન શા માટે જરૂરી છે?", a: "સાચું અને ચોક્કસ માપ મેળવવા માટે યુનિટ કન્વર્ઝન જરૂરી છે." },
  { q: "MM ને Micron માં કેવી રીતે કન્વર્ટ કરવામાં આવે છે?", a: "MM × 1000 કરવામાં આવે છે." },
  { q: "Micron ને MM માં કેવી રીતે કન્વર્ટ કરવામાં આવે છે?", a: "Micron ÷ 1000 કરવામાં આવે છે." },
  { q: "1 MM કેટલા Micron બરાબર છે?", a: "1 MM = 1000 Micron." },
  { q: "1 Micron કેટલા MM બરાબર છે?", a: "1 Micron = 0.001 MM." },
  { q: "Inch ને MM માં કેવી રીતે કન્વર્ટ કરવામાં આવે છે?", a: "Inch × 25.4 કરવામાં આવે છે." },
  { q: "1 Inch કેટલા MM બરાબર છે?", a: "1 Inch = 25.4 MM." },
  { q: "MM ને Inch માં કેવી રીતે કન્વર્ટ કરવામાં આવે છે?", a: "MM ÷ 25.4 કરવામાં આવે છે." },
  { q: "CM ને MM માં કેવી રીતે કન્વર્ટ કરવામાં આવે છે?", a: "CM × 10 કરવામાં આવે છે." },
  { q: "12.0 MM કેટલા Micron બરાબર છે?", a: "12.0 MM = 12,000 Micron." },
  { q: "3 Inch કેટલા MM બરાબર છે?", a: "3 Inch = 76.2 MM." },
  { q: "0.5 Inch કેટલા MM બરાબર છે?", a: "0.5 Inch = 12.7 MM." }
]},
{ id: "c2-6", no: "2.6", title: "વર્નિયર કેલિપર (Vernier Caliper)", qs: [
  { q: "વર્નિયર કેલિપર શું છે?", a: "વર્નિયર કેલિપર એક પ્રિસિઝન લિનિયર માપન સાધન છે, જે બહારના, અંદરના અને ઊંડાઈના માપ લેવા માટે વપરાય છે." },
  { q: "વર્નિયર કેલિપરની મેટ્રિક પદ્ધતિમાં સામાન્ય Least Count કેટલી હોય છે?", a: "સામાન્ય રીતે 0.02 mm." },
  { q: "વર્નિયર કેલિપરના મુખ્ય બે સ્કેલ કયા છે?", a: "મેઈન સ્કેલ અને વર્નિયર સ્કેલ." },
  { q: "વર્નિયર કેલિપર કયા સિદ્ધાંત પર કાર્ય કરે છે?", a: "બે અલગ ગ્રેજ્યુએશન ધરાવતા સ્કેલના તફાવતના સિદ્ધાંત પર." },
  { q: "વર્નિયર કેલિપરના Fixed Jaws નો ઉપયોગ શા માટે થાય છે?", a: "બહારના અને અંદરના માપ લેવા માટે." },
  { q: "Movable Jaws શું છે?", a: "વર્નિયર સ્લાઈડ સાથે જોડાયેલો અને બીમ પર ગતિ કરતો ભાગ Movable Jaws કહેવાય છે." },
  { q: "Depth Bar નો ઉપયોગ શા માટે થાય છે?", a: "ઊંડાઈ માપવા માટે." },
  { q: "વર્નિયર કેલિપરનું Least Count શું છે?", a: "માપી શકાય તેવી સૌથી નાની કિંમતને Least Count કહે છે." },
  { q: "Least Count નું સૂત્ર શું છે?", a: "Least Count = 1 MSD − 1 VSD." },
  { q: "વર્નિયર કેલિપરના મુખ્ય ઉપયોગ કયા છે?", a: "બહારનો વ્યાસ, અંદરનો વ્યાસ, લંબાઈ, પહોળાઈ, ઊંડાઈ, સ્લોટ અને ગ્રૂવ માપવા." },
  { q: "વર્નિયર કેલિપરની સામાન્ય મેટ્રિક રેન્જ કઈ છે?", a: "150 mm, 250 mm, 300 mm અને 600 mm." },
  { q: "ડાયલ વર્નિયર કેલિપર શું છે?", a: "વર્નિયર સ્કેલની જગ્યાએ ડાયલ ઇન્ડિકેટર લગાવેલું હોય તે વર્નિયર કેલિપરને ડાયલ વર્નિયર કેલિપર કહે છે." },
  { q: "ડાયલ વર્નિયર કેલિપરનો મુખ્ય ફાયદો શું છે?", a: "તેનું રીડિંગ સરળ અને સ્પષ્ટ હોવાથી માનવીય ભૂલ ઓછી થાય છે." },
  { q: "ડાયલ વર્નિયર કેલિપર કયા મિકેનિઝમથી કાર્ય કરે છે?", a: "રેક અને પીનિયન મિકેનિઝમથી." },
  { q: "ડાયલ વર્નિયર કેલિપરથી કયા માપ લઈ શકાય છે?", a: "બાહ્ય, આંતરિક અને ઊંડાઈના માપ લઈ શકાય છે." },
  { q: "ડિજિટલ વર્નિયર કેલિપર શું છે?", a: "ડિજિટલ ડિસ્પ્લે પર માપ દર્શાવતું આધુનિક પ્રિસિઝન માપન સાધન ડિજિટલ વર્નિયર કેલિપર છે." },
  { q: "ડિજિટલ વર્નિયર કેલિપરની સામાન્ય રેન્જ કઈ છે?", a: "0–150 mm, 0–200 mm અને 0–300 mm." },
  { q: "ડિજિટલ વર્નિયર કેલિપરથી માપ લેતાં પહેલાં શું કરવું જોઈએ?", a: "વર્કપીસ સાફ કરીને કેલિપરનું ON, જરૂરી Unit અને ZERO સેટિંગ તપાસવું જોઈએ." },
  { q: "ડિજિટલ વર્નિયર કેલિપરનો મુખ્ય ગેરફાયદો શું છે?", a: "તે બેટરી પર આધારિત છે અને સામાન્ય વર્નિયર કેલિપર કરતાં ખર્ચાળ છે." },
  { q: "વર્નિયર હાઈટ ગેજ શું છે?", a: "વર્કપીસની ચોક્કસ ઊંચાઈ માપવા તથા માર્કિંગ અને લેઆઉટ માટે વપરાતું પ્રિસિઝન સાધન છે." },
  { q: "વર્નિયર હાઈટ ગેજના મુખ્ય ભાગો કયા છે?", a: "Base, Beam, Vernier Slide, Fine Setting Device, Vernier Plate, Locking Screw અને Scriber." },
  { q: "વર્નિયર હાઈટ ગેજમાં Scriber નો ઉપયોગ શા માટે થાય છે?", a: "વર્કપીસ પર ચોક્કસ માર્કિંગ અને લેઆઉટ કરવા માટે." },
  { q: "વર્નિયર હાઈટ ગેજનો ઉપયોગ કયા સાધન સાથે કરવામાં આવે છે?", a: "સરફેસ પ્લેટ સાથે." },
  { q: "વર્નિયર હાઈટ ગેજ વાપરતી વખતે કઈ સાવચેતી રાખવી જોઈએ?", a: "સરફેસ પ્લેટ સ્વચ્છ રાખવી, સ્ક્રાઈબર પર વધારે દબાણ ન કરવું અને સાધનને કટિંગ ટૂલ્સથી દૂર રાખવું." },
  { q: "વર્નિયર ડેપ્થ ગેજનો ઉપયોગ શા માટે થાય છે?", a: "વસ્તુ, હોલ, સ્લોટ અથવા ખાંચાની ઊંડાઈ માપવા માટે થાય છે." }
]},
{ id: "c2-11", no: "2.11", title: "માઈક્રોમીટર (Micrometer)", qs: [
  { q: "માઈક્રોમીટર શું છે?", a: "માઈક્રોમીટર એક ડાયરેક્ટ લિનિયર પ્રિસિઝન મેઝરિંગ ઇન્સ્ટ્રુમેન્ટ છે, જે ખૂબ ચોકસાઈથી માપ લેવા માટે વપરાય છે." },
  { q: "આઉટસાઇડ માઈક્રોમીટરનો ઉપયોગ શેના માટે થાય છે?", a: "જોબના બહારના માપો, જેમ કે બહારનો વ્યાસ અને જાડાઈ માપવા માટે." },
  { q: "માઈક્રોમીટરનું મેટ્રિક Least Count કેટલું હોય છે?", a: "0.01 mm." },
  { q: "માઈક્રોમીટર કયા સિદ્ધાંત પર કાર્ય કરે છે?", a: "સ્ક્રુ અને નટના સિદ્ધાંત પર કાર્ય કરે છે." },
  { q: "માઈક્રોમીટરના મુખ્ય ભાગો કયા છે?", a: "ફ્રેમ, સ્લીવ, થિમ્બલ, સ્પિન્ડલ, એન્વીલ, લોક નટ અને રેચેટ સ્ટોપ." },
  { q: "માઈક્રોમીટરમાં એન્વીલનું કાર્ય શું છે?", a: "એન્વીલ સ્થિર મેઝરિંગ ફેસ તરીકે કામ કરે છે." },
  { q: "સ્પિન્ડલનું કાર્ય શું છે?", a: "સ્પિન્ડલ આગળ-પાછળ ખસીને વર્કપીસનું માપ લેવામાં મદદ કરે છે." },
  { q: "રેચેટ સ્ટોપનો ઉપયોગ શા માટે થાય છે?", a: "મેઝરિંગ ફેસ પર સમાન અને યોગ્ય દબાણ આપવા માટે." },
  { q: "માઈક્રોમીટરથી માપ લેતી વખતે રેચેટનો ઉપયોગ કેવી રીતે કરવો?", a: "રેચેટમાંથી “કટ-કટ” અવાજ આવે ત્યાં સુધી ફેરવવું અને ત્યારબાદ માપ લેવું." },
  { q: "માઈક્રોમીટરની સામાન્ય મેટ્રિક રેન્જ કઈ છે?", a: "0–25 mm, 25–50 mm, 50–75 mm વગેરે." },
  { q: "Positive Zero Error શું છે?", a: "સાધનનું રીડિંગ વધારે આવે તેને Positive Zero Error કહે છે અને તે ભૂલ બાદ કરવામાં આવે છે." },
  { q: "Negative Zero Error શું છે?", a: "સાધનનું રીડિંગ ઓછું આવે તેને Negative Zero Error કહે છે અને તે ભૂલ ઉમેરવામાં આવે છે." },
  { q: "Inside Micrometer શું છે?", a: "હોલ, બોર અથવા પાઇપનો અંદરનો વ્યાસ માપવા માટે વપરાતું પ્રિસિઝન માપન સાધન છે." },
  { q: "Inside Micrometer નું Least Count કેટલું હોય છે?", a: "મેટ્રિક પદ્ધતિમાં સામાન્ય રીતે 0.01 mm." },
  { q: "Inside Micrometer ના મુખ્ય ભાગો કયા છે?", a: "Carbide Jaws, Locking Knob, Spindle, Sleeve, Thimble અને Ratchet Stop." },
  { q: "Inside Micrometer નો ઉપયોગ કરીને બોરની Parallelism કેવી રીતે ચકાસી શકાય?", a: "બોરની ટોચ, મધ્ય અને તળિયે રીડિંગ લઈ શકાય. ત્રણેય રીડિંગ સમાન હોય તો બોર સમાંતર ગણાય." },
  { q: "Micrometer Depth Gauge નો ઉપયોગ શા માટે થાય છે?", a: "હોલ, સ્લોટ અને સ્ટેપની ઊંડાઈ ચોકસાઈથી માપવા માટે." },
  { q: "Micrometer Depth Gauge નું Least Count કેટલું છે?", a: "0.01 mm." },
  { q: "Micrometer Depth Gauge માં Extension Rod નો ઉપયોગ શા માટે થાય છે?", a: "25 mm કરતાં વધુ ઊંડાઈ માપવા માટે." },
  { q: "Micrometer Depth Gauge માં 0.5 mm પિચ અને 50 વિભાગ હોય તો Least Count કેટલું થશે?", a: "Least Count = 0.5 ÷ 50 = 0.01 mm." },
  { q: "Digital Micrometer શું છે?", a: "ડિજિટલ ડિસ્પ્લે પર માપ સીધું દર્શાવતું પ્રિસિઝન માપન સાધન છે." },
  { q: "Digital Micrometer નો મુખ્ય ફાયદો શું છે?", a: "ગણતરી કર્યા વગર માપ સીધું ડિસ્પ્લે પર જોઈ શકાય છે અને માનવીય ભૂલ ઓછી થાય છે." },
  { q: "Vernier Caliper અને Micrometer વચ્ચેનો મુખ્ય તફાવત શું છે?", a: "વર્નિયર કેલિપરથી બહારનું, અંદરનું અને ઊંડાઈનું માપ એક જ સાધનથી લઈ શકાય છે, જ્યારે અલગ પ્રકારના માઈક્રોમીટર અલગ માપ માટે વપરાય છે." },
  { q: "Vernier Caliper અને Micrometerની રેન્જમાં શું તફાવત છે?", a: "વર્નિયર કેલિપરની રેન્જ સામાન્ય રીતે વધારે હોય છે, જેમ કે 0–300 mm, જ્યારે માઈક્રોમીટરની રેન્જ ઓછી હોય છે, જેમ કે 0–25 mm અથવા 25–50 mm." },
  { q: "Vernier Caliper અને Micrometerના Least Countમાં શું તફાવત છે?", a: "સામાન્ય મેટ્રિક વર્નિયર કેલિપરનું Least Count 0.02 mm અને માઈક્રોમીટરનું Least Count 0.01 mm હોય છે. તેથી માઈક્રોમીટર વધુ ચોકસાઈથી માપ લઈ શકે છે." }
]},
{ id: "c2-15", no: "2.15", title: "ડાયલ ટેસ્ટ ઇન્ડિકેટર અને સ્ટેન્ડ (Dial Test Indicator)", qs: [
  { q: "ડાયલ ટેસ્ટ ઇન્ડિકેટર (DTI) શું છે?", a: "DTI એક ચોકસાઈવાળું માપન સાધન છે, જે ખૂબ જ નાના હલનચલન અથવા ફેરફારને મોટું કરીને ડાયલ પર દર્શાવે છે." },
  { q: "DTI કયા સિદ્ધાંત પર કાર્ય કરે છે?", a: "પ્લન્જર અથવા સ્ટાઈલસની નાની રેખીય હલનચલનને મિકેનિઝમ દ્વારા મેગ્નિફાય કરીને પોઇન્ટરની વર્તુળાકાર ગતિમાં ફેરવવાના સિદ્ધાંત પર." },
  { q: "DTI ના મુખ્ય બે પ્રકાર કયા છે?", a: "પ્લન્જર ટાઈપ અને લીવર ટાઈપ DTI." },
  { q: "Plunger Type DTI માં Contact Point નું કાર્ય શું છે?", a: "વર્કપીસની સપાટીને સ્પર્શ કરીને તેનું નાનું હલનચલન મેળવવાનું કામ કરે છે." },
  { q: "DTI માં Spindle નું કાર્ય શું છે?", a: "Contact Point સાથે જોડાયેલું સ્પિન્ડલ ઉપર-નીચે હલનચલન કરે છે." },
  { q: "DTI માં Stem નો ઉપયોગ શા માટે થાય છે?", a: "DTI ને સ્ટેન્ડ અથવા હોલ્ડરમાં ફિક્સ કરવા માટે." },
  { q: "Outer Dial શું દર્શાવે છે?", a: "Outer Dial મુખ્ય સ્કેલ પર ખૂબ સૂક્ષ્મ માપ અથવા ફેરફાર દર્શાવે છે." },
  { q: "DTI માં Pointer નું કાર્ય શું છે?", a: "માપનું મુખ્ય રીડિંગ દર્શાવવાનું કામ કરે છે." },
  { q: "Bezel નો ઉપયોગ શા માટે થાય છે?", a: "ડાયલનો ઝીરો સેટ કરવા માટે." },
  { q: "Tolerance Hand નો ઉપયોગ શા માટે થાય છે?", a: "મર્યાદા સેટ કરીને OK અથવા NOT OK ચકાસવા માટે." },
  { q: "DTI નો ઉપયોગ CNC મશીનમાં શા માટે થાય છે?", a: "Run-out, Flatness, Alignment અને Parallelism ચકાસવા માટે." },
  { q: "Run-out શું છે?", a: "ફરતા ભાગમાં તેની નિર્ધારિત ધરીની સરખામણીમાં થતો રેડિયલ અથવા અક્ષીય ફેરફાર Run-out કહેવાય છે." },
  { q: "Lever Type DTI કેવી રીતે કાર્ય કરે છે?", a: "લીવર અને ગિયર મિકેનિઝમ દ્વારા હલનચલનને મેગ્નિફાય કરીને કાર્ય કરે છે." },
  { q: "Lever Type DTI માં Plungerની જગ્યાએ શું હોય છે?", a: "સામાન્ય રીતે બોલ ટાઈપ સ્ટાઈલસ હોય છે." },
  { q: "Lever Type DTI ક્યારે વધુ ઉપયોગી છે?", a: "જ્યાં Plunger Type DTI સરળતાથી વાપરી શકાતું ન હોય ત્યાં Lever Type DTI વધુ ઉપયોગી છે." },
  { q: "DTI નો ઉપયોગ Flatness ચેક કરવા કેવી રીતે થાય છે?", a: "DTI ને સ્ટેન્ડમાં ફિટ કરીને વર્કપીસની સપાટી પર ફેરવવાથી પોઇન્ટરના ફેરફાર પરથી Flatness ચકાસી શકાય છે." },
  { q: "DTI નો ઉપયોગ Parallelism ચેક કરવા શા માટે થાય છે?", a: "બે સપાટી અથવા ભાગો એકબીજાની સમાંતર છે કે નહીં તે ચકાસવા માટે." },
  { q: "Concentricity શું છે?", a: "હોલ અને શાફ્ટ જેવી ગોળાકાર સપાટીઓની એક જ કેન્દ્રરેખા સાથેની ગોઠવણીને Concentricity કહે છે." },
  { q: "DTI ની સામાન્ય મેટ્રિક ચોકસાઈ કેટલી હોય છે?", a: "સામાન્ય રીતે 0.01 mm અને વધુ ચોકસાઈ માટે 0.001 mm સુધી." },
  { q: "DTI સ્ટેન્ડનો ઉપયોગ શા માટે થાય છે?", a: "DTI ને સ્થિર અને યોગ્ય સ્થિતિમાં રાખવા માટે સ્ટેન્ડનો ઉપયોગ થાય છે." },
  { q: "DTI સ્ટેન્ડના મુખ્ય પ્રકાર કયા છે?", a: "મેગ્નેટિક સ્ટેન્ડ, ફ્લેક્સિબલ પોસ્ટ વાળો મેગ્નેટિક સ્ટેન્ડ અને કાસ્ટ આયર્ન બેઝ વાળો જનરલ પર્પઝ હોલ્ડર." },
  { q: "મેગ્નેટિક સ્ટેન્ડ કેવી રીતે કામ કરે છે?", a: "બેઝમાં રહેલા મેગ્નેટને ON કરવાથી સ્ટેન્ડ ધાતુની સપાટી પર મજબૂતીથી ચોંટી જાય છે અને OFF કરવાથી છૂટો થઈ જાય છે." },
  { q: "ફ્લેક્સિબલ પોસ્ટ વાળા મેગ્નેટિક સ્ટેન્ડનો ફાયદો શું છે?", a: "તેની પોસ્ટને વાળીને DTI ને જરૂરી સ્થિતિમાં સરળતાથી ગોઠવી શકાય છે." },
  { q: "DTI વડે માપ લેવાની શરૂઆત કેવી રીતે કરવામાં આવે છે?", a: "વર્કપીસને સરફેસ પ્લેટ અથવા મશીન ટેબલ પર રાખી, DTI ને સ્ટેન્ડમાં ફિટ કરીને સ્ટાઈલસને સપાટી સાથે સ્પર્શમાં રાખવામાં આવે છે અને શરૂઆતનું રીડિંગ લેવામાં આવે છે." },
  { q: "DTI માં પોઇન્ટર Clockwise અથવા Anticlockwise ફરે તો શું સમજાય છે?", a: "પોઇન્ટરની દિશા પ્રમાણે વર્કપીસમાં Positive અથવા Negative Variation થયેલ છે તે જાણી શકાય છે." }
]},
{ id: "c3-0", no: "3.0", title: "ગેજ ના પ્રકાર (Types of Gauges)", qs: [
  { q: "બોર ડાયલ ગેજનો ઉપયોગ શેના માટે થાય છે?", a: "આંતરિક વ્યાસ (I.D.) માપવા માટે થાય છે." },
  { q: "બોર ડાયલ ગેજ કયા પ્રકારનું સાધન છે?", a: "પ્રિસિઝન મેઝરિંગ ઇન્સ્ટ્રુમેન્ટ છે." },
  { q: "બોર ડાયલ ગેજથી કઈ ખામીઓ તપાસી શકાય છે?", a: "Roundness, Taper અને Ovality તપાસી શકાય છે." },
  { q: "બોર ડાયલ ગેજમાં Dial Gaugeનું કાર્ય શું છે?", a: "માપમાં થતો ફેરફાર Pointer દ્વારા દર્શાવવાનું." },
  { q: "બોર ડાયલ ગેજમાં Gripનું કાર્ય શું છે?", a: "ગેજને હાથથી સ્થિર રીતે પકડવાનું." },
  { q: "Replacement Rod શા માટે વપરાય છે?", a: "અલગ-અલગ સાઈઝના બોર માપવા માટે." },
  { q: "બોર ડાયલ ગેજમાં Zero Setting શા માટે કરવામાં આવે છે?", a: "સ્ટાન્ડર્ડ સાઈઝથી બોરનો ફેરફાર ચોક્કસ રીતે જાણવા માટે." },
  { q: "બોર ડાયલ ગેજમાં વાસ્તવિક બોર સાઈઝનું સૂત્ર શું છે?", a: "Actual Bore Size = Standard Size ± Dial Reading." },
  { q: "રેડિયસ ગેજનો ઉપયોગ શેના માટે થાય છે?", a: "Internal અને External Radius ચકાસવા માટે." },
  { q: "રેડિયસ ગેજ કઈ સામગ્રીમાંથી બનાવવામાં આવે છે?", a: "ઉચ્ચ ગુણવત્તાવાળી સ્ટીલ શીટમાંથી." },
  { q: "રેડિયસ ગેજની બ્લેડ પર શું દર્શાવેલું હોય છે?", a: "બ્લેડની Radius Size દર્શાવેલી હોય છે." },
  { q: "રેડિયસ ગેજથી Radius કેવી રીતે ચકાસવામાં આવે છે?", a: "યોગ્ય બ્લેડ પસંદ કરીને વર્કપીસની Radius સાથે મેચ કરવામાં આવે છે." },
  { q: "રેડિયસ ગેજ અને વર્કપીસ વચ્ચે પ્રકાશ દેખાય તો શું સમજાય?", a: "Radius યોગ્ય રીતે મેચ થતી નથી." },
  { q: "ફીલર ગેજ શું છે?", a: "અલગ-અલગ જાડાઈની પાતળી સ્ટીલ બ્લેડ્સનો સેટ છે." },
  { q: "ફીલર ગેજનો મુખ્ય ઉપયોગ શું છે?", a: "બે સપાટીઓ વચ્ચેનો ગેપ અથવા ક્લીયરન્સ માપવા માટે." },
  { q: "B.I.S. મુજબ ફિલર ગેજ કેટલા સેટમાં મળે છે?", a: "સેટ 1, 2, 3 અને 4 એમ ચાર સેટમાં મળે છે." },
  { q: "ફીલર ગેજ સામાન્ય રીતે કેટલી રેન્જમાં મળે છે?", a: "સામાન્ય રીતે 0.03 mm થી 1.00 mm સુધી." },
  { q: "Limit Gaugeનો ઉપયોગ શા માટે થાય છે?", a: "કમ્પોનન્ટ નિર્ધારિત સાઈઝ અને ટોલરન્સમાં છે કે નહીં તે ઝડપથી તપાસવા." },
  { q: "Go અને No-Go Principle શું છે?", a: "GO છેડો કમ્પોનન્ટમાં દાખલ થવો જોઈએ અને NO-GO છેડો દાખલ થવો જોઈએ નહીં." },
  { q: "Plain Plug Gaugeનો ઉપયોગ શેના માટે થાય છે?", a: "હોલની લિમિટ ચકાસવા માટે." },
  { q: "Thread Ring Gaugeનો ઉપયોગ શેના માટે થાય છે?", a: "External Threadની ચોકસાઈ ચકાસવા માટે." },
  { q: "Snap Gaugeનો ઉપયોગ શેના માટે થાય છે?", a: "શાફ્ટના વ્યાસ જેવા બહારના પરિમાણો ઝડપથી ચકાસવા માટે." },
  { q: "Thread Plug Gaugeનો ઉપયોગ શેના માટે થાય છે?", a: "Internal Threadની ચોકસાઈ ચકાસવા માટે." },
  { q: "Slip Gauge એટલે શું?", a: "ચોક્કસ લંબાઈ માપવા માટે વપરાતો Precision Gauge Block છે." },
  { q: "Slip Gaugeના Grade 00, 0, I અને II શું દર્શાવે છે?", a: "તેઓ Slip Gaugeની ચોકસાઈ અને ઉપયોગનો સ્તર દર્શાવે છે; Grade 00 સૌથી વધુ ચોકસાઈવાળો છે." }
]},
{ id: "c4-0", no: "4.0", title: "એન્જિનિયરિંગ ડ્રોઇંગ (Fundamentals of Engineering Drawing)", qs: [
  { q: "કમ્યુનિકેશન એટલે શું?", a: "માહિતી અથવા અનુભવની આપ-લે કરવાની પ્રક્રિયાને કમ્યુનિકેશન કહે છે." },
  { q: "સંદેશાવ્યવહાર માટેનું માધ્યમ શું છે?", a: "ભાષા સંદેશાવ્યવહારનું માધ્યમ છે." },
  { q: "Sign Languageની એક મર્યાદા જણાવો.", a: "તેમાં ગેરસમજ થવાની શક્યતા રહે છે." },
  { q: "Vocal Languageની મુખ્ય મર્યાદા શું છે?", a: "બોલનાર અને સાંભળનારને એક જ ભાષાનું જ્ઞાન હોવું જરૂરી છે." },
  { q: "Computer Language સામાન્ય સંદેશાવ્યવહાર માટે કેમ યોગ્ય નથી?", a: "તે મુખ્યત્વે પ્રોગ્રામર માટે ઉપયોગી છે." },
  { q: "Engineering Drawingને શું કહેવામાં આવે છે?", a: "એન્જિનિયરની ભાષા અથવા સાર્વત્રિક ભાષા કહેવામાં આવે છે." },
  { q: "એન્જિનિયરિંગ ડ્રોઇંગનું મહત્વ શું છે?", a: "પાર્ટ અથવા કમ્પોનન્ટની ડિઝાઇન અને ટેક્નિકલ વિગતો સ્પષ્ટ રીતે દર્શાવવા માટે જરૂરી છે." },
  { q: "“One picture is worth one thousand words” નો અર્થ શું છે?", a: "એક રેખાચિત્ર ઘણી બધી માહિતી થોડા સમયમાં સ્પષ્ટ રીતે દર્શાવી શકે છે." },
  { q: "ગ્રાફિક કમ્યુનિકેશન એટલે શું?", a: "ગ્રાફિક ઈમેજ દ્વારા સંદેશા અથવા વિચારોની આપ-લેને ગ્રાફિક કમ્યુનિકેશન કહે છે." },
  { q: "ડ્રોઇંગના મુખ્ય બે પ્રકાર કયા છે?", a: "Technical Drawing અને Artistic Drawing." },
  { q: "Technical Drawingનો ઉપયોગ કયા ક્ષેત્રોમાં થાય છે?", a: "સિવિલ, ઇલેક્ટ્રિકલ, મિકેનિકલ અને આર્કિટેક્ચર જેવા ક્ષેત્રોમાં થાય છે." },
  { q: "Engineering Drawingના અભ્યાસનો એક હેતુ જણાવો.", a: "ઉદ્યોગમાં ઉપયોગી ડ્રોઇંગ વાંચવાની અને સમજવાની કુશળતા વિકસાવવી." },
  { q: "ડ્રોઇંગ શીટ ફોલ્ડ કરતી વખતે શું ધ્યાન રાખવું જોઈએ?", a: "ફોલ્ડ એવી રીતે કરવું જોઈએ કે ટાઇટલ બ્લોક દેખાય." },
  { q: "ટ્રેસિંગ શીટ ફોલ્ડ કરવી જોઈએ?", a: "ના, ટ્રેસિંગ શીટને ફોલ્ડ કરવી નહીં." },
  { q: "Object Lineનો ઉપયોગ શેના માટે થાય છે?", a: "વસ્તુની દેખાતી બહારની ધાર અને આઉટલાઇન દર્શાવવા માટે." },
  { q: "Dotted Lineનો ઉપયોગ શેના માટે થાય છે?", a: "વસ્તુની દેખાતી ન હોય તેવી ધારો દર્શાવવા માટે." },
  { q: "Center Lineનો ઉપયોગ શેના માટે થાય છે?", a: "વર્તુળાકાર અથવા નળાકાર ભાગોની સેન્ટર ધરી દર્શાવવા માટે." },
  { q: "Construction Lineનો ઉપયોગ શેના માટે થાય છે?", a: "ડ્રોઇંગની રચના અથવા construction કરવા માટે." },
  { q: "1st Angle Projectionમાં Plan ક્યાં દોરવામાં આવે છે?", a: "Elevationની નીચે દોરવામાં આવે છે." },
  { q: "3rd Angle Projectionમાં Plan ક્યાં દોરવામાં આવે છે?", a: "Elevationની ઉપર દોરવામાં આવે છે." },
  { q: "1st Angle Projectionમાં Right Side View ક્યાં હોય છે?", a: "Elevationની ડાબી બાજુ હોય છે." },
  { q: "3rd Angle Projectionમાં Right Side View ક્યાં હોય છે?", a: "Elevationની જમણી બાજુ હોય છે." },
  { q: "2nd અને 4th Angle Projectionનો ઉપયોગ કેમ થતો નથી?", a: "તેમાં Plan અને Elevation એકબીજા પર ઓવરલેપ થાય છે, તેથી વ્યુ સ્પષ્ટ ઓળખી શકાતો નથી." },
  { q: "Orthographic Drawing દોરતા પહેલાં શું કરવું જોઈએ?", a: "ઓબ્જેક્ટની મનમાં કલ્પના (Visualization) કરી 1st કે 3rd Angle Projection નક્કી કરવું જોઈએ." },
  { q: "Orthographic Drawingમાં મુખ્ય વ્યુ કયા હોય છે?", a: "સામાન્ય રીતે Front View (Elevation), Top View (Plan) અને Side View દોરવામાં આવે છે." }
]},
{ id: "c5-0", no: "5.0", title: "લિમિટ અને ફિટ (Limit & Fit)", qs: [
  { q: "લિમિટ પદ્ધતિ શું છે?", a: "કોમ્પોનન્ટનું માપ નિર્ધારિત મહત્તમ અને ન્યૂનતમ લિમિટમાં રાખવાની પદ્ધતિને લિમિટ પદ્ધતિ કહે છે." },
  { q: "લિમિટ પદ્ધતિની જરૂરિયાત શા માટે પડે છે?", a: "માસ પ્રોડક્શનમાં દરેક કોમ્પોનન્ટ એકસરખી સાઈઝમાં બનાવી શકાતું નથી, તેથી સ્વીકાર્ય માપની છૂટછાટ રાખવા લિમિટ પદ્ધતિ જરૂરી છે." },
  { q: "લિમિટ પદ્ધતિના સ્ટાન્ડર્ડ કયા છે?", a: "ISO, BSS અને DIN મુખ્ય સ્ટાન્ડર્ડ છે." },
  { q: "Basic Size એટલે શું?", a: "જેના આધાર પર વિચલન આપવામાં આવે છે તેને Basic Size કહે છે." },
  { q: "Actual Size એટલે શું?", a: "ઉત્પાદન થયા પછી માપવાથી મળતી વાસ્તવિક સાઈઝને Actual Size કહે છે." },
  { q: "Limit of Size એટલે શું?", a: "કોમ્પોનન્ટની મહત્તમ અને ન્યૂનતમ મંજૂર સાઈઝને Limit of Size કહે છે." },
  { q: "Maximum Limit શું છે?", a: "કોમ્પોનન્ટની સૌથી મોટી મંજૂર સાઈઝને Maximum Limit કહે છે." },
  { q: "Minimum Limit શું છે?", a: "કોમ્પોનન્ટની સૌથી નાની મંજૂર સાઈઝને Minimum Limit કહે છે." },
  { q: "BIS મુજબ Hole શું છે?", a: "કોમ્પોનન્ટના આંતરિક ભાગને Hole કહે છે." },
  { q: "BIS મુજબ Shaft શું છે?", a: "કોમ્પોનન્ટના બાહ્ય ભાગને Shaft કહે છે." },
  { q: "Deviation એટલે શું?", a: "Basic Size અને સંબંધિત સાઈઝ વચ્ચેના તફાવતને Deviation કહે છે." },
  { q: "Upper Deviation શું છે?", a: "Maximum Limit અને Basic Size વચ્ચેના તફાવતને Upper Deviation કહે છે." },
  { q: "Lower Deviation શું છે?", a: "Minimum Limit અને Basic Size વચ્ચેના તફાવતને Lower Deviation કહે છે." },
  { q: "Tolerance શું છે?", a: "Maximum Limit અને Minimum Limit વચ્ચેના તફાવતને Tolerance કહે છે.\nસૂત્ર: Tolerance = Maximum Limit − Minimum Limit" },
  { q: "Zero Line શું છે?", a: "Basic Size દર્શાવતી રેખાને Zero Line કહે છે." },
  { q: "Fundamental Deviation શું છે?", a: "Zero Lineની સાપેક્ષે Tolerance Zone ની સ્થિતિ નક્કી કરતું મૂળભૂત વિચલન Fundamental Deviation કહેવાય છે." },
  { q: "BIS પદ્ધતિમાં Fundamental Deviation કેટલા હોય છે?", a: "કુલ 25 Fundamental Deviations હોય છે." },
  { q: "Hole માટે કયા અક્ષરોનો ઉપયોગ થાય છે?", a: "Hole માટે Capital Letters A થી Z નો ઉપયોગ થાય છે." },
  { q: "Shaft માટે કયા અક્ષરોનો ઉપયોગ થાય છે?", a: "Shaft માટે Small Letters a થી z નો ઉપયોગ થાય છે." },
  { q: "H Hole ની વિશેષતા શું છે?", a: "H Hole નું Lower Deviation Zero હોય છે." },
  { q: "Fit એટલે શું?", a: "Hole અને Shaft એસેમ્બલી વખતે તેમની સાઈઝના તફાવતને Fit કહે છે." },
  { q: "Fit ના મુખ્ય પ્રકાર કયા છે?", a: "Clearance Fit\nInterference Fit\nTransition Fit" },
  { q: "Clearance Fit શું છે?", a: "જેમાં Hole હંમેશા Shaft કરતાં મોટો હોય અને Clearance હંમેશા Positive હોય તેને Clearance Fit કહે છે." },
  { q: "Interference Fit શું છે?", a: "જેમાં Shaft હંમેશા Hole કરતાં મોટો હોય અને Clearance Negative હોય તેને Interference Fit કહે છે." },
  { q: "Hole Basis System શું છે?", a: "Hole ની સાઈઝ સ્થિર રાખીને Shaft ની સાઈઝમાં ફેરફાર કરીને વિવિધ પ્રકારની Fit મેળવવાની પદ્ધતિને Hole Basis System કહે છે. તેમાં H Hole લેવામાં આવે છે અને તેનું Lower Deviation Zero હોય છે." }
]},
{ id: "c6-0", no: "6.0", title: "Industrial Hand Tools", qs: [
  { q: "L-Key Set નો ઉપયોગ શા માટે થાય છે?", a: "હેક્સાગોન સોકેટવાળા સ્ક્રૂ અને બોલ્ટને ટાઈટ અને લુઝ કરવા માટે." },
  { q: "L-Key કયા મટિરિયલમાંથી બને છે?", a: "હાર્ડન સ્ટીલમાંથી." },
  { q: "Spanner નો ઉપયોગ શા માટે થાય છે?", a: "નટ અને બોલ્ટને ટાઈટ અથવા લુઝ કરવા માટે." },
  { q: "Spanner કયા મટિરિયલમાંથી બનાવવામાં આવે છે?", a: "ડ્રોપ ફોર્જડ સ્ટીલ, હાઈ ટેન્સાઈલ સ્ટીલ અથવા એલોય સ્ટીલમાંથી." },
  { q: "Ring Spanner ની ખાસિયત શું છે?", a: "તે નટ અથવા બોલ્ટને મજબૂત રીતે પકડીને સ્લિપ થવાની શક્યતા ઘટાડે છે." },
  { q: "હેમરના બે મુખ્ય ભાગ કયા છે?", a: "Head અને Handle." },
  { q: "હેમરનો ઉપયોગ કયા કામમાં થાય છે?", a: "પન્ચિંગ, બેન્ડિંગ, સ્ટ્રેટનિંગ, ચીપીંગ, ફોર્જિંગ અને રિવેટિંગમાં." },
  { q: "હેમર હેડના મુખ્ય ભાગો કયા છે?", a: "Face, Pein, Cheek અને Eye Hole." },
  { q: "Pein ના આધારે હેમરના કયા પ્રકાર છે?", a: "Ball Pein, Cross Pein અને Straight Pein Hammer." },
  { q: "હેમરનું સામાન્ય વજન કેટલું હોય છે?", a: "આશરે 125 ગ્રામથી 1500 ગ્રામ." },
  { q: "Bench Vice શું છે?", a: "વર્કપીસને મજબૂતીથી પકડવા માટેનું Work Holding Device છે." },
  { q: "Bench Vice ને બીજા કયા નામે ઓળખવામાં આવે છે?", a: "Parallel Jaw Vice અથવા Fitter Vice." },
  { q: "Bench Vice ની સાઈઝ કઈ રીતે દર્શાવવામાં આવે છે?", a: "Jaw ની પહોળાઈ પરથી." },
  { q: "Bench Vice ના મુખ્ય ભાગો કયા છે?", a: "Fixed Jaw, Movable Jaw, Hard Jaw, Spindle, Handle, Box Nut અને Spring." },
  { q: "Bench Vice ના Spindle માં સામાન્ય રીતે કયો Thread હોય છે?", a: "Square Thread." },
  { q: "Hacksaw નો ઉપયોગ શા માટે થાય છે?", a: "વર્કપીસમાં કટિંગ, સ્લોટ અને ખાંચા બનાવવા માટે." },
  { q: "Hacksaw Frame ના મુખ્ય પ્રકાર કયા છે?", a: "Solid Frame અને Adjustable Frame." },
  { q: "Hacksaw Blade ની સ્ટાન્ડર્ડ લંબાઈ કેટલી હોય છે?", a: "250 mm અને 300 mm." },
  { q: "Hacksawing કરતી વખતે Return Stroke માં દબાણ આપવું જોઈએ?", a: "નહીં, દબાણ માત્ર Forward Stroke દરમિયાન આપવું." },
  { q: "Filing શું છે?", a: "ફાઈલ દ્વારા વર્કપીસનું વધારાનું મટિરિયલ ચિપ્સના સ્વરૂપમાં દૂર કરવાની પ્રક્રિયા." },
  { q: "ફાઈલના મુખ્ય ભાગો કયા છે?", a: "Heel, Tang, Face, Edge અને Tip/Point." },
  { q: "ફાઈલ કયા મટિરિયલમાંથી બને છે?", a: "સામાન્ય રીતે High Carbon Steel અથવા High Grade Alloy Steelમાંથી." },
  { q: "ફાઈલનું વર્ગીકરણ કયા આધારે થાય છે?", a: "Length, Grade, Cut અને Shapeના આધારે." },
  { q: "ફાઈલના Grade ના પ્રકાર કયા છે?", a: "Rough, Bastard, Second Cut, Smooth અને Dead Smooth." },
  { q: "ફાઈલના મુખ્ય આકાર કયા છે?", a: "Flat, Hand, Square, Round, Half Round, Triangular અને Knife Edge File." }
]},
{ id: "c7-0", no: "7.0", title: "CNC પરિચય અને CNC & VMC મશીન ના ભાગો", qs: [
  { q: "CNC નું સંપૂર્ણ નામ શું છે?", a: "Computer Numerical Control." },
  { q: "CNC શું છે?", a: "કમ્પ્યુટર દ્વારા નિયંત્રિત થતી મશીનને CNC મશીન કહે છે." },
  { q: "CNC મશીનમાં કયા કોડનો ઉપયોગ થાય છે?", a: "G-Code અને M-Code." },
  { q: "CNC Lathe Machine નો ઉપયોગ શેના માટે થાય છે?", a: "Turning, Facing અને Threading માટે." },
  { q: "VMC નો ઉપયોગ શેના માટે થાય છે?", a: "Flat surface, Slot, Pocket અને જટિલ આકાર બનાવવા માટે." },
  { q: "CNC Grinder નો ઉપયોગ શા માટે થાય છે?", a: "ઉચ્ચ ચોકસાઈ અને સ્મૂથ સપાટી મેળવવા માટે." },
  { q: "CNC Drilling Machine નો ઉપયોગ શા માટે થાય છે?", a: "મટિરિયલમાં ચોક્કસ માપના Hole બનાવવા માટે." },
  { q: "CNC Plasma Cutter નો ઉપયોગ શા માટે થાય છે?", a: "મેટલ શીટને ઝડપથી કાપવા માટે." },
  { q: "CNC Laser Cutter નો ઉપયોગ શા માટે થાય છે?", a: "લેસર બીમથી ઉચ્ચ ચોકસાઈથી મટિરિયલ કાપવા માટે." },
  { q: "Control Panel નું કાર્ય શું છે?", a: "CNC મશીનના વિવિધ કાર્યો અને Axis ને નિયંત્રિત કરવાનું." },
  { q: "Tool Turret શું છે?", a: "CNC Lathe માં Cutting Tools રાખવા અને જરૂરી Tool ને Cutting Position પર લાવવા માટેનું સાધન." },
  { q: "Tailstock નો ઉપયોગ શા માટે થાય છે?", a: "લાંબી અથવા પાતળી વર્કપીસને સપોર્ટ આપવા માટે." },
  { q: "CNC Spindle નું મુખ્ય કાર્ય શું છે?", a: "Chuck અથવા Tool ને ફેરવવાનું અને જરૂરી RPM આપવાનું." },
  { q: "Servo Motor નું કાર્ય શું છે?", a: "ચોક્કસ ગતિ અને સ્થિતિ સાથે મશીનના ભાગોને ચલાવવાનું." },
  { q: "Hydraulic Oil Tank નો ઉપયોગ શા માટે થાય છે?", a: "Chuck Clamp/De-Clamp અને અન્ય Hydraulic કાર્ય માટે તેલ પૂરું પાડવા." },
  { q: "Lubrication Oil Tank નું કાર્ય શું છે?", a: "Moving Parts માં ઓઇલ આપી ઘર્ષણ ઘટાડવાનું." },
  { q: "Coolant Tank નું કાર્ય શું છે?", a: "Cutting દરમિયાન Tool અને Workpiece ની ગરમી ઘટાડવાનું." },
  { q: "PLC Panel ને શું કહેવામાં આવે છે?", a: "CNC મશીનનું Automation Brain." },
  { q: "CNC Stabilizer નું કાર્ય શું છે?", a: "મશીનને સ્થિર વોલ્ટેજ પૂરું પાડવાનું અને Electrical Parts ને સુરક્ષિત રાખવાનું." },
  { q: "ATC નું સંપૂર્ણ નામ શું છે અને તેનો ઉપયોગ શું છે?", a: "Automatic Tool Changer; તેનો ઉપયોગ VMC માં Tool આપમેળે બદલવા માટે થાય છે." },
  { q: "VMC Hand Wheel ને શું કહેવામાં આવે છે?", a: "MPG (Manual Pulse Generator)." },
  { q: "VMC Spindle નું કાર્ય શું છે?", a: "Tool Holder ને પકડીને Tool ને જરૂરી RPM પર ફેરવવાનું." },
  { q: "VMC Table નો ઉપયોગ શા માટે થાય છે?", a: "Workpiece અને Fixture ને રાખવા તથા ક્લેમ્પ કરવા માટે." },
  { q: "VMC માટે સામાન્ય Air Pressure કેટલું હોય છે?", a: "સામાન્ય રીતે 6 થી 8 Bar." },
  { q: "CNC Software ને શું કહેવામાં આવે છે?", a: "CNC મશીનનું “Brain” કહેવામાં આવે છે; તે G-Code/M-Code વાંચીને મશીનને નિયંત્રિત કરે છે." }
]},
{ id: "c7-5", no: "7.5", title: "CNC Machine Keys", qs: [
  { q: "POSITION KEY નો ઉપયોગ શા માટે થાય છે?", a: "મશીનની X, Y, Z Axis Position જોવા માટે." },
  { q: "CNC Lathe માં કઈ Axis ની Position જોવા મળે છે?", a: "X-Axis અને Z-Axis." },
  { q: "VMC મશીનમાં કઈ Axis હોય છે?", a: "X, Y અને Z Axis." },
  { q: "Cycle Time શું છે?", a: "Program ના Start Block થી End Block સુધીનો કુલ સમય." },
  { q: "PROGRAM KEY નો ઉપયોગ શા માટે થાય છે?", a: "Program ને જોવા અને Edit કરવા માટે." },
  { q: "OFFSET SETTING KEY નો ઉપયોગ શા માટે થાય છે?", a: "Tool અને Work Offset Set કરવા માટે." },
  { q: "Geometric Offset શું છે?", a: "Tool નું X અને Z Axis Offset." },
  { q: "Wear Offset નો ઉપયોગ શા માટે થાય છે?", a: "Tool ઘસાઈ જાય ત્યારે Micron પ્રમાણે Correction કરવા." },
  { q: "Work Shift Offset શું છે?", a: "Geometric Offset ને + અથવા – માં Shift કરવા માટે." },
  { q: "G54 થી G59 શું દર્શાવે છે?", a: "Work Coordinate System." },
  { q: "CANCEL KEY નો ઉપયોગ શા માટે થાય છે?", a: "ખોટો Data અથવા Program દૂર કરવા." },
  { q: "INPUT KEY નો ઉપયોગ શા માટે થાય છે?", a: "Program અથવા Data Enter કરવા." },
  { q: "SYSTEM KEY નો ઉપયોગ શા માટે થાય છે?", a: "Machine ના Parameters જોવા અથવા Set કરવા." },
  { q: "MESSAGE KEY નો ઉપયોગ શા માટે થાય છે?", a: "Machine Alarm ની Detail જોવા." },
  { q: "CUSTOM GRAPH KEY નો ઉપયોગ શા માટે થાય છે?", a: "Program ચલાવ્યા વગર Tool Path જોવા." },
  { q: "ALTER KEY નો ઉપયોગ શા માટે થાય છે?", a: "Program માં ખોટો Data Replace કરવા." },
  { q: "INSERT KEY નો ઉપયોગ શા માટે થાય છે?", a: "Program માં Data/Block Insert કરવા." },
  { q: "DELETE KEY નો ઉપયોગ શા માટે થાય છે?", a: "Block, Word અથવા Program Delete કરવા." },
  { q: "PAGE UP / PAGE DOWN નો ઉપયોગ શા માટે થાય છે?", a: "Screen પર Page Scroll કરવા." },
  { q: "CURSOR KEY નો ઉપયોગ શા માટે થાય છે?", a: "Program માં Data પર Cursor ખસેડવા." },
  { q: "RESET KEY નો ઉપયોગ શા માટે થાય છે?", a: "Program Restart અને સામાન્ય Alarm Clear કરવા." },
  { q: "EOB નું સંપૂર્ણ નામ શું છે?", a: "End Of Block." },
  { q: "ORIGIN KEY નો ઉપયોગ શા માટે થાય છે?", a: "પસંદ કરેલી Axis ને Zero Set કરવા." },
  { q: "HOME G28 નો ઉપયોગ શા માટે થાય છે?", a: "Machine ને Home Position પર લઈ જવા." },
  { q: "SEND અને RECV નો ઉપયોગ શા માટે થાય છે?", a: "SEND: Program બહાર Transfer કરવા.\nRECV: Program Machine માં Receive કરવા." }
]},
{ id: "c7-6", no: "7.6", title: "CNC & VMC Machine ON/OFF અને Homing", qs: [
  { q: "CNC મશીન ON કરવાની પ્રથમ પ્રક્રિયા શું છે?", a: "Main Switch ON કરવી." },
  { q: "Main Switch પછી શું ON કરવું?", a: "Stabilizer ON કરવું." },
  { q: "CNC મશીનની Main Switch ક્યાં હોય છે?", a: "મશીનના જમણા ભાગમાં." },
  { q: "Control Panel પર કઈ Key ON કરવી?", a: "Green Colorની “ON” Key." },
  { q: "Emergency Switch ક્યારે ON કરવી?", a: "Screen પર Display આવ્યા પછી." },
  { q: "Machine Control ON કરવા કઈ Key દબાવવી?", a: "RESET Key." },
  { q: "CNC Turning Homing માટે કયો Mode Select કરાય છે?", a: "MPG Mode." },
  { q: "Position Key દબાવવાથી શું દેખાય છે?", a: "X અને Z Axis ની Position." },
  { q: "Homing દરમિયાન MPG માં કેટલો Feed Select કરાય છે?", a: "100 Micron." },
  { q: "CNC Turning માં Z Axis ને કેટલા mm સુધી લાવવામાં આવે છે?", a: "–50.0 mm." },
  { q: "CNC Turning માં X Axis ને કેટલા mm સુધી લાવવામાં આવે છે?", a: "–50.0 mm." },
  { q: "CNC Turning માં Reference લેવા કયો Mode Select થાય છે?", a: "REF Mode." },
  { q: "CNC Turning માં X Axis ને Reference પર કેવી રીતે લાવવામાં આવે છે?", a: "X+ Key દબાવીને." },
  { q: "CNC Turning માં Z Axis ને Reference પર કેવી રીતે લાવવામાં આવે છે?", a: "Z+ Key દબાવીને." },
  { q: "CNC Turning Honing માટે MDI માં કયો Command નાખવામાં આવે છે?", a: "M03 S100." },
  { q: "M03 S100 Command થી શું થાય છે?", a: "Spindle Clockwise દિશામાં ફરે છે." },
  { q: "Honing દરમિયાન Spindle કેટલા સમય સુધી ફેરવાય છે?", a: "આશરે 30 સેકન્ડ." },
  { q: "VMC મશીન ON કરવાની શરૂઆત કેવી રીતે થાય છે?", a: "Main Switch ON કરીને." },
  { q: "VMC માં Stabilizer શા માટે ON કરવામાં આવે છે?", a: "વીજ વોલ્ટેજ સ્થિર રાખવા માટે." },
  { q: "VMC મશીનમાં Air Dryer શા માટે ON કરવો જરૂરી છે?", a: "Compressed Air માંથી Moisture દૂર કરવા માટે." },
  { q: "VMC Homing માં કઈ ત્રણ Axis Reference કરવામાં આવે છે?", a: "X, Y અને Z Axis." },
  { q: "VMC માં X Axis ને કઈ દિશામાં Home કરવામાં આવે છે?", a: "X– દિશામાં." },
  { q: "VMC માં Z અને Y Axis ને કઈ દિશામાં Home કરવામાં આવે છે?", a: "Z+ અને Y+ દિશામાં." },
  { q: "VMC માં Jog Magazine Reference શા માટે કરવામાં આવે છે?", a: "ATC Magazine ને Home Position પર લાવવા માટે." },
  { q: "VMC Honing માટે MDI માં કયો Command નાખવામાં આવે છે?", a: "M03 S500 નાખીને EOB અને INSERT દબાવવામાં આવે છે; Spindle આશરે 30 સેકન્ડ ફેરવવામાં આવે છે." }
]},
{ id: "c7-8", no: "7.8", title: "Types of Mode", qs: [
  { q: "EDIT MODE નો ઉપયોગ શા માટે થાય છે?", a: "નવો Program બનાવવા અને જૂના Program માં સુધારા કરવા." },
  { q: "EDIT MODE થી Program Delete કરી શકાય છે?", a: "હા, Program Delete કરી શકાય છે." },
  { q: "JOG MODE ને બીજા કયા નામે ઓળખવામાં આવે છે?", a: "MANUAL MODE." },
  { q: "JOG MODE નો મુખ્ય ઉપયોગ શું છે?", a: "X, Y, Z Axis ને મેન્યુઅલી ખસેડવા." },
  { q: "JOG MODE માં કયા કામ કરી શકાય છે?", a: "Coolant ON/OFF, Spindle CW/CCW અને Tailstock IN/OUT." },
  { q: "MPG નું સંપૂર્ણ નામ શું છે?", a: "Manual Pulse Generator." },
  { q: "MPG MODE નો ઉપયોગ શા માટે થાય છે?", a: "Axis ને ચોક્કસ માઇક્રોન મુજબ ચલાવવા." },
  { q: "CNC Lathe માં MPG દ્વારા કઈ Axis ચલાવી શકાય છે?", a: "X અને Z Axis." },
  { q: "CNC Milling/VMC માં MPG દ્વારા કઈ Axis ચલાવી શકાય છે?", a: "X, Y અને Z Axis." },
  { q: "MPG માં કયા Micron Step ઉપલબ્ધ હોય છે?", a: "1, 10, 100 અને 1000 Micron." },
  { q: "Z.R.N નું સંપૂર્ણ નામ શું છે?", a: "Zero Return Mode." },
  { q: "Z.R.N MODE નો ઉપયોગ શા માટે થાય છે?", a: "તમામ Axis ને Home Position પર લાવવા માટે." },
  { q: "મશીન ON કર્યા પછી કયો Mode Homing માટે ઉપયોગી છે?", a: "Z.R.N Mode." },
  { q: "Tool બદલ્યા પછી કયો Mode ઉપયોગી છે?", a: "Z.R.N Mode." },
  { q: "AUTO MODE નો ઉપયોગ શા માટે થાય છે?", a: "Program પ્રમાણે Tool ને Automatic ચલાવવા." },
  { q: "MDI નું સંપૂર્ણ નામ શું છે?", a: "Manual Data Input." },
  { q: "MDI MODE નો ઉપયોગ શા માટે થાય છે?", a: "નાના Commands ટાઈપ કરીને તરત Execute કરવા." },
  { q: "MDI માં કયા Commands ચલાવી શકાય છે?", a: "Spindle, Coolant, Homing અને Tailstock ના Commands." },
  { q: "લેથ મશીનમાં નાના Manual Jobs માટે કયો Mode ઉપયોગી છે?", a: "MDI Mode." },
  { q: "RAPID MODE નો ઉપયોગ શા માટે થાય છે?", a: "Axis ને Non-Cutting વિસ્તારમાં ઝડપથી ખસેડવા." },
  { q: "RAPID MODE ક્યારે ઉપયોગ કરવો જોઈએ?", a: "Non-Cutting વિસ્તારમાં." },
  { q: "DNC નું સંપૂર્ણ નામ શું છે?", a: "Direct Numerical Control." },
  { q: "DNC MODE નો ઉપયોગ શા માટે થાય છે?", a: "Computer અને CNC Machine વચ્ચે Data Exchange કરવા." },
  { q: "DNC દ્વારા લાંબો Program કેવી રીતે ચલાવી શકાય?", a: "Computer પરથી સીધો CNC Machine માં મોકલીને." },
  { q: "CNC ના મુખ્ય Modes કયા છે?", a: "EDIT, JOG, MPG, ZRN, AUTO, MDI, RAPID અને DNC Modes." }
]},
{ id: "c7-9", no: "7.9", title: "CNC ના લાભો-ગેરલાભો અને Jaws", qs: [
  { q: "CNC નું પૂરું નામ શું છે?", a: "Computer Numerical Control." },
  { q: "CNC મશીનનો મુખ્ય લાભ કયો છે?", a: "ઉચ્ચ ચોકસાઈ (High Accuracy)." },
  { q: "CNC મશીનમાં માનવ ભૂલ ઓછી થવાથી શું મળે છે?", a: "વધુ ચોકસાઈ મળે છે." },
  { q: "CNC મશીનનો ઉત્પાદન દર કેવો હોય છે?", a: "ઉત્પાદન દર ઊંચો હોય છે." },
  { q: "CNC મશીનમાં માનવ શ્રમ ઓછો કેમ પડે છે?", a: "ઓટોમેશનને કારણે." },
  { q: "CNC મશીનને કઈ રીતે ચલાવી શકાય છે?", a: "MDI અથવા પ્રોગ્રામ દ્વારા." },
  { q: "CNC મશીન પર કયા પ્રકારના આકારો બનાવી શકાય છે?", a: "જટિલ 2D અને 3D આકારો બનાવી શકાય છે." },
  { q: "CNC મશીન સતત કેટલા સમય સુધી કામ કરી શકે છે?", a: "24×7 એટલે કે દિવસ-રાત સતત કામ કરી શકે છે." },
  { q: "CNC મશીનમાં Consistent Quality એટલે શું?", a: "દરેક ભાગ સમાન ગુણવત્તા અને માપદંડ મુજબ બનાવવો." },
  { q: "CNC મશીનનો મુખ્ય ગેરલાભ કયો છે?", a: "તેનો પ્રારંભિક ખર્ચ ખૂબ વધારે હોય છે." },
  { q: "CNC મશીનની જાળવણી માટે કોની જરૂર પડે છે?", a: "સ્પેશિયલ ટેકનિશિયન અને યોગ્ય ટૂલ્સની જરૂર પડે છે." },
  { q: "CNC મશીન ચલાવવા માટે કેવા ઓપરેટરની જરૂર પડે છે?", a: "તાલીમપ્રાપ્ત અને કુશળ ઓપરેટરની જરૂર પડે છે." },
  { q: "CNC પ્રોગ્રામિંગ માટે કયા કોડનું જ્ઞાન જરૂરી છે?", a: "G-code અને M-codeનું જ્ઞાન જરૂરી છે." },
  { q: "CNC મશીનમાં Breakdown થવાથી શું થાય છે?", a: "મશીનની કામગીરી અને ઉત્પાદન બંધ થઈ શકે છે." },
  { q: "CNC મશીન માટે Power Backup શા માટે જરૂરી છે?", a: "વીજ પુરવઠો બંધ થાય ત્યારે કામગીરી ચાલુ રાખવા માટે." },
  { q: "Jaws શું છે?", a: "Jaws એ Chuck પર લગાવવામાં આવતા ધાતુના ભાગો છે, જે Workpieceને પકડી રાખે છે." },
  { q: "Jaws ક્યાં લગાવવામાં આવે છે?", a: "CNC Lathe મશીનના Chuck પર." },
  { q: "Jawsનું મુખ્ય કાર્ય શું છે?", a: "Workpieceને મજબૂતીથી પકડી રાખવાનું અને હલનચલન અટકાવવાનું." },
  { q: "Jawsના મુખ્ય પ્રકાર કયા છે?", a: "Hard Jaws અને Soft Jaws." },
  { q: "Hard Jaws કઈ ધાતુમાંથી બનાવવામાં આવે છે?", a: "Carbon Steel અથવા Alloy Steelમાંથી." },
  { q: "Hard Jaws કેવી રીતે તૈયાર કરવામાં આવે છે?", a: "તે પહેલેથી ચોક્કસ આકારમાં Pre-machined હોય છે." },
  { q: "Hard Jawsનો ઉપયોગ કયા કામ માટે થાય છે?", a: "સામાન્ય અને વારંવાર બનતી Repeated Jobs માટે." },
  { q: "Soft Jaws કઈ ધાતુમાંથી બનાવવામાં આવે છે?", a: "Mild Steel અથવા Aluminumમાંથી." },
  { q: "Soft Jawsને Workpieceના આકાર પ્રમાણે કેવી રીતે તૈયાર કરવામાં આવે છે?", a: "જરૂરિયાત મુજબ Machining કરીને તૈયાર કરવામાં આવે છે." },
  { q: "Soft Jawsના મુખ્ય ફાયદા શું છે?", a: "તે વધુ ચોકસાઈ આપે છે અને Workpiece પર ઓછા Marks પાડે છે." }
]},
{ id: "c7-11", no: "7.11", title: "CNC Lathe Operations", qs: [
  { q: "Facing Operation શું છે?", a: "Workpieceની આગળની સપાટીને સમતળ અને ચોક્કસ બનાવવાની પ્રક્રિયાને Facing કહે છે." },
  { q: "Facingનો મુખ્ય હેતુ શું છે?", a: "અસમાન સપાટી દૂર કરીને Flat અને ચોક્કસ સપાટી મેળવવી." },
  { q: "Facing કયા Operation પહેલાં કરવામાં આવે છે?", a: "સામાન્ય રીતે Facing દરેક Jobમાં પ્રથમ Operation તરીકે કરવામાં આવે છે." },
  { q: "Turning Operation શું છે?", a: "ફરતા Workpieceની બહારની સપાટી પરથી Material દૂર કરીને જરૂરી Diameter અને Shape મેળવવાની પ્રક્રિયા Turning છે." },
  { q: "Turningના મુખ્ય પ્રકાર કયા છે?", a: "Straight Turning, Taper Turning અને Step Turning." },
  { q: "Straight Turning શું છે?", a: "Workpiece પર સીધી Cylindrical સપાટી બનાવવાની પ્રક્રિયા." },
  { q: "Taper Turning શું છે?", a: "Workpiece પર Conical અથવા Taper Shape બનાવવાની પ્રક્રિયા." },
  { q: "Step Turning શું છે?", a: "અલગ-અલગ Diameterના Steps બનાવવાની પ્રક્રિયા." },
  { q: "Drilling Operation શું છે?", a: "Workpieceમાં ગોળ Hole બનાવવાની પ્રક્રિયાને Drilling કહે છે." },
  { q: "Drilling માટે કયા Toolનો ઉપયોગ થાય છે?", a: "Drill Bitનો ઉપયોગ થાય છે." },
  { q: "Drillingનો ઉપયોગ કયા Operation માટે તૈયારી કરવા થાય છે?", a: "Boring અને Threading માટે તૈયારી કરવા થાય છે." },
  { q: "Boring Operation શું છે?", a: "પહેલેથી બનાવેલા Holeને ચોક્કસ Diameter, Alignment અને Surface Finish આપવાની પ્રક્રિયા Boring છે." },
  { q: "Boring માટે કયા Toolનો ઉપયોગ થાય છે?", a: "Boring Barનો ઉપયોગ થાય છે." },
  { q: "Boringને કયા પ્રકારનું Operation માનવામાં આવે છે?", a: "Boringને Precision Operation માનવામાં આવે છે." },
  { q: "Radius Operation શું છે?", a: "Workpieceના Sharp Corner અથવા Edgeને ગોળ બનાવવાની પ્રક્રિયાને Radius Operation કહે છે." },
  { q: "Radius Operationનો એક મુખ્ય લાભ જણાવો.", a: "તે Sharp Edge દૂર કરીને Stress Concentration ઘટાડે છે." },
  { q: "Chamfer Operation શું છે?", a: "Workpieceના Edge પર ચોક્કસ Angle પર કાપ મૂકવાની પ્રક્રિયાને Chamfer કહે છે." },
  { q: "સામાન્ય રીતે કેટલા Degreeનો Chamfer વપરાય છે?", a: "સામાન્ય રીતે 45° Chamfer વપરાય છે." },
  { q: "Threading Operation શું છે?", a: "Workpieceની અંદર અથવા બહાર Spiral Shapeના Thread બનાવવાની પ્રક્રિયા Threading છે." },
  { q: "Threadingના બે પ્રકાર જણાવો.", a: "External Thread અને Internal Thread." },
  { q: "Threading માટેના સામાન્ય G-Codes કયા છે?", a: "G76, G92 અને G32." },
  { q: "Grooving Operation શું છે?", a: "Workpiece પર સાંકડો ખાચો (Groove) બનાવવાની પ્રક્રિયાને Grooving કહે છે." },
  { q: "Parting Operationનો મુખ્ય હેતુ શું છે?", a: "તૈયાર થયેલા Final Componentને Raw Materialથી અલગ કરવાનો." },
  { q: "Knurling Operation શું છે?", a: "Workpieceની સપાટી પર દબાણથી Straight, Slant અથવા Diamond Pattern બનાવવાની પ્રક્રિયા Knurling છે." },
  { q: "Knurlingમાં Material Remove થાય છે?", a: "ના. Knurlingમાં Material Remove થતું નથી, પરંતુ Toolના દબાણથી સપાટી પર Pattern બનાવવામાં આવે છે." }
]},
{ id: "c8-0", no: "8.0", title: "CNC Axis, CNC Lathe અને VMC", qs: [
  { q: "CNC Axis શું છે?", a: "CNC મશીનમાં Tool અથવા Table જે નિયંત્રિત દિશામાં હલનચલન કરે તેને Axis કહે છે." },
  { q: "CNC મશીનમાં સામાન્ય રીતે કયા Axis હોય છે?", a: "X, Y અને Z Axis." },
  { q: "X, Y અને Z Axis એકબીજાને કેટલા ખૂણે હોય છે?", a: "90°ના ખૂણે." },
  { q: "X-axisનું મુખ્ય કાર્ય શું છે?", a: "X-axis આડી દિશામાં Left–Right હલનચલન માટે વપરાય છે." },
  { q: "CNC Latheમાં X-axis શું નિયંત્રિત કરે છે?", a: "Workpieceનો Diameter નિયંત્રિત કરે છે." },
  { q: "VMCમાં X-axisનું કાર્ય શું છે?", a: "Tableને Left–Right હલાવે છે." },
  { q: "Y-axisનું મુખ્ય કાર્ય શું છે?", a: "Y-axis Front–Back હલનચલન માટે વપરાય છે." },
  { q: "CNC Latheમાં Y-axis સામાન્ય રીતે હોય છે?", a: "ના, સામાન્ય CNC Latheમાં Y-axis ઉપલબ્ધ હોતો નથી." },
  { q: "VMCમાં Y-axis શું કરે છે?", a: "Tableને Front–Back હલાવે છે." },
  { q: "Z-axisનું મુખ્ય કાર્ય શું છે?", a: "Z-axis Cutting Depth અને મશીનિંગની દિશા નિયંત્રિત કરે છે." },
  { q: "CNC Latheમાં Z-axis શું નિયંત્રિત કરે છે?", a: "Workpieceની Length નિયંત્રિત કરે છે." },
  { q: "VMCમાં Z-axis શું હલાવે છે?", a: "Spindleને Up–Down હલાવે છે." },
  { q: "CNC Lathe શું છે?", a: "CNC Lathe એવી મશીન છે જેમાં Workpiece ફરે છે અને Cutting Tool નિયંત્રિત Axis પર હલનચલન કરીને Machining કરે છે." },
  { q: "CNC Latheનો મુખ્ય ઉપયોગ શેના માટે થાય છે?", a: "મુખ્યત્વે Cylindrical Parts બનાવવા માટે." },
  { q: "CNC Latheમાં કેટલા મુખ્ય Axis હોય છે?", a: "X અને Z બે મુખ્ય Axis હોય છે." },
  { q: "CNC Latheમાં Workpiece ફરે છે કે Tool?", a: "CNC Latheમાં Workpiece ફરે છે." },
  { q: "CNC Latheની મુખ્ય Operations કઈ છે?", a: "Turning, Facing, Grooving, Thread Cutting અને Boring." },
  { q: "VMCનું પૂરું નામ શું છે?", a: "Vertical Machining Center." },
  { q: "VMCમાં Spindle કેવી સ્થિતિમાં હોય છે?", a: "Spindle ઊભી (Vertical) સ્થિતિમાં હોય છે." },
  { q: "VMCમાં Tool ફરે છે કે Workpiece?", a: "VMCમાં Cutting Tool ફરે છે." },
  { q: "VMCમાં કયા Axis હોય છે?", a: "X, Y અને Z Axis." },
  { q: "VMCના મુખ્ય ઉપયોગો કયા છે?", a: "Milling, Drilling, Slotting, Pocket Machining અને 2D/3D Contour Machining." },
  { q: "CNC Lathe અને VMCમાં મુખ્ય તફાવત શું છે?", a: "CNC Latheમાં Workpiece ફરે છે, જ્યારે VMCમાં Cutting Tool ફરે છે." },
  { q: "CNC Lathe અને VMCમાં X-axisનું કાર્ય શું છે?", a: "CNC Latheમાં X-axis Diameter નિયંત્રિત કરે છે, જ્યારે VMCમાં Tableને Left–Right હલાવે છે." },
  { q: "CNC Lathe અને VMCમાં કયા પ્રકારના Parts બનાવી શકાય છે?", a: "CNC Latheમાં મુખ્યત્વે Cylindrical Parts અને VMCમાં Flat, 2D તથા 3D Parts બનાવી શકાય છે." }
]},
{ id: "c9-0", no: "9.0", title: "CNC Insert અને Tool Holder", qs: [
  { q: "CNC Insert શું છે?", a: "CNC મશીનમાં Cutting માટે Tool Holderમાં ફિટ કરવામાં આવતો બદલી શકાય તેવો Cutting Toolનો ભાગ Insert કહેવાય છે." },
  { q: "CNC Insert કઈ સામગ્રીમાંથી બને છે?", a: "Carbide, Ceramic, CBN અને PCD જેવી Hard Materialમાંથી બને છે." },
  { q: "Insert ઘસાઈ જાય ત્યારે શું કરવામાં આવે છે?", a: "Insertને બદલી નાખવામાં આવે છે." },
  { q: "CNC Insertનો એક મુખ્ય ફાયદો શું છે?", a: "આખું Tool બદલવાની જરૂર પડતી નથી, માત્ર Insert બદલી શકાય છે." },
  { q: "CNMG Insertનો મુખ્ય ઉપયોગ શું છે?", a: "Rough Turning અને Heavy Cutting માટે." },
  { q: "CNMG Insertનો આકાર કયો હોય છે?", a: "80° Diamond Shape." },
  { q: "TNMG Insertનો મુખ્ય ઉપયોગ શું છે?", a: "Finish Turning અને Semi-Finishing માટે." },
  { q: "DNMG Insertનો મુખ્ય ઉપયોગ શું છે?", a: "Profile Turning અને Taper Turning માટે." },
  { q: "VNMG Insertની ખાસિયત શું છે?", a: "તેનો 35° Nose Angle હોવાથી Sharp Cutting અને Fine Finishing મળે છે." },
  { q: "WNMG Insertનો ઉપયોગ શેના માટે થાય છે?", a: "Rough Turning અને Heavy Material Removal માટે." },
  { q: "CCMT Insertનો મુખ્ય ઉપયોગ શું છે?", a: "Boring અને Internal Turning માટે." },
  { q: "DCMT Insertનો ઉપયોગ કયા કામમાં થાય છે?", a: "Finish Turning, Boring અને Profile Turningમાં." },
  { q: "RCMT Insertનો આકાર કયો હોય છે?", a: "Round Shape." },
  { q: "RCMT Insertનો મુખ્ય ઉપયોગ શું છે?", a: "Rough Turning, Radius Turning અને Profile Machining માટે." },
  { q: "MGMN Insertનો ઉપયોગ શેના માટે થાય છે?", a: "Grooving અને Parting Operation માટે." },
  { q: "ER Insertનો ઉપયોગ કયા પ્રકારના Thread માટે થાય છે?", a: "External Threading માટે." },
  { q: "IR Insertનો ઉપયોગ કયા પ્રકારના Thread માટે થાય છે?", a: "Internal Threading માટે." },
  { q: "SPMG Insertનો ઉપયોગ શેના માટે થાય છે?", a: "Drilling અને Deep Hole Drilling માટે." },
  { q: "Tool Holder શું છે?", a: "Insertને મજબૂતીથી પકડી રાખવા અને યોગ્ય Angle તથા Height પર રાખવા માટે વપરાતું Tool Holder કહેવાય છે." },
  { q: "Tool Holder ક્યાં ફિટ કરવામાં આવે છે?", a: "CNC મશીનના Turret પર ફિટ કરવામાં આવે છે." },
  { q: "Tool Holderનું મુખ્ય કાર્ય શું છે?", a: "Insertને મજબૂતીથી પકડી રાખવું અને Cutting દરમિયાન Stability જાળવવી." },
  { q: "External Turning Holderનો ઉપયોગ શેના માટે થાય છે?", a: "Workpieceના બહારના Diameter એટલે કે OD Machining માટે." },
  { q: "Boring Barનો ઉપયોગ શેના માટે થાય છે?", a: "પહેલેથી બનાવેલા Holeને મોટું અને ચોક્કસ કરવા માટે." },
  { q: "Internal Grooving Toolનો ઉપયોગ શેના માટે થાય છે?", a: "Holeની અંદર Groove અથવા Undercut બનાવવા માટે." },
  { q: "Knurling Toolનો ઉપયોગ શેના માટે થાય છે?", a: "Workpieceની સપાટી પર Pattern બનાવી Grip સુધારવા માટે." }
]},
{ id: "c9-3", no: "9.3", title: "VMC Tools, Cutters અને Operations", qs: [
  { q: "End Mill Cutter શું છે?", a: "End Mill Cutter એ VMCમાં વપરાતું કટર છે, જેની Side અને End બંને તરફ Cutting Edges હોય છે." },
  { q: "End Mill Cutterનો ઉપયોગ ક્યાં થાય છે?", a: "Slot, Pocket, Contour અને Profile Milling માટે." },
  { q: "End Mill Cutterના મુખ્ય પ્રકાર કયા છે?", a: "Flat End Mill, Ball Nose End Mill અને Corner Radius End Mill." },
  { q: "Face Mill Cutterનો ઉપયોગ શેના માટે થાય છે?", a: "મોટા વિસ્તારની સપાટીને સમતળ બનાવવા માટે." },
  { q: "Side and Shoulder Cutterનો ઉપયોગ શેના માટે થાય છે?", a: "Slot, Keyway, Groove અને Shoulder Cutting માટે." },
  { q: "Drillનું મુખ્ય કાર્ય શું છે?", a: "Workpieceમાં ગોળ (Round) Hole બનાવવાનું." },
  { q: "Drillના મુખ્ય ભાગો કયા છે?", a: "Shank, Body, Flutes, Cutting Edge અને Point Angle." },
  { q: "સામાન્ય Twist Drillનો Point Angle કેટલો હોય છે?", a: "સામાન્ય રીતે 118°." },
  { q: "Center Drillનો ઉપયોગ શા માટે થાય છે?", a: "Drilling પહેલાં ચોક્કસ Center બનાવવા માટે." },
  { q: "Spot Drillનો મુખ્ય ફાયદો શું છે?", a: "તે વધુ Rigid હોવાથી Accurate Drilling માટે ઉપયોગી છે." },
  { q: "Drill બનાવવા માટે કઈ બે મુખ્ય સામગ્રી વપરાય છે?", a: "HSS અને Carbide." },
  { q: "Tapનો ઉપયોગ શેના માટે થાય છે?", a: "Holeની અંદર Internal Thread બનાવવા માટે." },
  { q: "Reamerનું મુખ્ય કાર્ય શું છે?", a: "Holeને ચોક્કસ Size અને Smooth Surface Finish આપવાનું." },
  { q: "Boring Toolનો ઉપયોગ શેના માટે થાય છે?", a: "પહેલેથી બનાવેલા Holeને મોટો અને વધુ Accurate બનાવવા માટે." },
  { q: "Chamfer Toolનો ઉપયોગ શેના માટે થાય છે?", a: "Edgeને Bevel આકાર આપવા અને Sharp Edge દૂર કરવા માટે." },
  { q: "Countersink Toolનો ઉપયોગ શેના માટે થાય છે?", a: "Flat Head Screw માટે Cone Shape Seat બનાવવા માટે." },
  { q: "VMCમાં Tool Holderનું કાર્ય શું છે?", a: "Toolને Spindleમાં મજબૂતીથી પકડી રાખવાનું." },
  { q: "VMC Tool Holderના પ્રકાર કયા છે?", a: "BT, CAT, HSK અને R8." },
  { q: "Coolantનો મુખ્ય ઉપયોગ શું છે?", a: "Cutting Areaને ઠંડુ રાખવું અને Tool Life વધારવી." },
  { q: "VMCમાં Facing Operation શું છે?", a: "Workpieceની ઉપરની સપાટીને સંપૂર્ણ સમતળ બનાવવાની પ્રક્રિયા." },
  { q: "Pocket Milling શું છે?", a: "Workpieceની અંદર ચોક્કસ આકારની ખોખલી જગ્યા બનાવવાની પ્રક્રિયા." },
  { q: "Slot Cutting શું છે?", a: "Workpieceમાં સીધી અથવા આકારવાળી ખાડી (Slot) બનાવવાની પ્રક્રિયા." },
  { q: "Reaming Operation શા માટે કરવામાં આવે છે?", a: "Holeને Final Size અને Smooth Surface Finish આપવા માટે." },
  { q: "Tapping Operation શું છે?", a: "Holeની અંદર Internal Thread બનાવવાની પ્રક્રિયા." },
  { q: "3D Profilingમાં કયા Toolનો ઉપયોગ થાય છે?", a: "સામાન્ય રીતે Ball Nose End Millનો ઉપયોગ થાય છે. તે Die, Mould અને 3D Components બનાવવા માટે ઉપયોગી છે." }
]},
{ id: "c10-0", no: "10.0", title: "CNC પ્રોગ્રામિંગ પરિચય", qs: [
  { q: "CNC Program શું છે?", a: "CNC મશીનમાં Jobનું Machining કરવા માટે લખવામાં આવતી સૂચનાઓના સમૂહને CNC Program કહે છે." },
  { q: "CNC Program મુખ્યત્વે કયા બે કોડથી બને છે?", a: "G-Code અને M-Codeથી." },
  { q: "CNC Programનો મુખ્ય હેતુ શું છે?", a: "Toolને Automatic રીતે Job પર જરૂરી Operations કરાવવાનો." },
  { q: "G-Code શું છે?", a: "G-Code એ Preparatory Function Code છે, જે CNC મશીનની મુખ્ય Machining Operationsને નિયંત્રિત કરે છે." },
  { q: "M-Code શું છે?", a: "M-Code એ Miscellaneous Function Code છે, જે મશીનની વિવિધ સહાયક ક્રિયાઓને નિયંત્રિત કરે છે." },
  { q: "A Alphabetનો CNCમાં શું ઉપયોગ છે?", a: "Angular Dimension એટલે કે ખૂણાની માપ દર્શાવવા માટે." },
  { q: "C Alphabetનો ઉપયોગ શેના માટે થાય છે?", a: "Chamfering Amount અને Tool Nose Radius માટે." },
  { q: "F Alphabet શું દર્શાવે છે?", a: "Feed Function અથવા Thread Lead દર્શાવે છે." },
  { q: "G Alphabetનો અર્થ શું છે?", a: "Preparatory Function એટલે G-Code." },
  { q: "H Alphabetનો ઉપયોગ શેના માટે થાય છે?", a: "Macro Function માટે." },
  { q: "I Alphabetનો ઉપયોગ શેના માટે થાય છે?", a: "Thread Taper Height માટે થાય છે." },
  { q: "M Alphabetનો અર્થ શું છે?", a: "Miscellaneous Function એટલે M-Code." },
  { q: "N Alphabet શું દર્શાવે છે?", a: "Sequence અથવા Block Number દર્શાવે છે." },
  { q: "O Alphabetનો ઉપયોગ શેના માટે થાય છે?", a: "Program Number દર્શાવવા માટે." },
  { q: "P Alphabetનો ઉપયોગ કયા કામ માટે થાય છે?", a: "Subprogram Number, Dwell, Branching અને Offset/Macro માટે થાય છે." },
  { q: "Q Alphabetનો ઉપયોગ શેના માટે થાય છે?", a: "Block End, Depth of Cut અને Macro Variable માટે." },
  { q: "R Alphabet શું દર્શાવે છે?", a: "Radius, Retraction અને Number of Cuts માટે વપરાય છે." },
  { q: "S Alphabetનો ઉપયોગ શેના માટે થાય છે?", a: "Spindle Speed Function માટે." },
  { q: "T Alphabet શું દર્શાવે છે?", a: "Tool Number અને Tool Offset દર્શાવે છે." },
  { q: "U Alphabetનો ઉપયોગ શેના માટે થાય છે?", a: "X-axisમાં Incremental Value અથવા X/Z Machining Allowance માટે." },
  { q: "W Alphabetનો ઉપયોગ શેના માટે થાય છે?", a: "Z-axisમાં Incremental Value અથવા Z-axis Allowance માટે." },
  { q: "X Alphabet શું દર્શાવે છે?", a: "X-axisનું Absolute Dimension એટલે CNC Latheમાં Diameter દર્શાવે છે." },
  { q: "Z Alphabet શું દર્શાવે છે?", a: "Z-axisનું Absolute Dimension એટલે CNC Latheમાં Length દર્શાવે છે." },
  { q: "CNC Latheમાં X અને Z Axisનો શું ઉપયોગ છે?", a: "X-axis Diameter નિયંત્રિત કરે છે અને Z-axis Workpieceની Length નિયંત્રિત કરે છે." },
  { q: "CNC Programming શા માટે જરૂરી છે?", a: "CNC મશીનને ચોક્કસ રીતે Tool Movement, Machining Operation અને Jobનું ઉત્પાદન Automatic રીતે કરાવવા માટે CNC Programming જરૂરી છે." }
]},
{ id: "c10-1", no: "10.1", title: "G-Code અને M-Code", qs: [
  { q: "G-Code શું છે?", a: "G-Code CNC મશીનને Tool અથવા Tableની Movement અને Machining માટેના આદેશ આપે છે." },
  { q: "CNC Programમાં G-Codeનું શું મહત્વ છે?", a: "CNC મશીનની મુખ્ય Machining અને Motion Operations નિયંત્રિત કરવા માટે G-Code જરૂરી છે." },
  { q: "G00 Codeનો ઉપયોગ શેના માટે થાય છે?", a: "Tool અથવા Tableને ઝડપથી Rapid Traverseમાં ખસેડવા માટે." },
  { q: "G01 Code શું દર્શાવે છે?", a: "Linear Interpolation એટલે સીધી રેખામાં Cutting માટે." },
  { q: "G02 અને G03નો ઉપયોગ શેના માટે થાય છે?", a: "G02 Clockwise અને G03 Counter-Clockwise Circular Interpolation માટે થાય છે." },
  { q: "G04 Code શું છે?", a: "G04 Dwell Code છે, જે Tool અથવા Spindleને ચોક્કસ સમય માટે રોકવા માટે વપરાય છે." },
  { q: "G20 અને G21નો ઉપયોગ શેના માટે થાય છે?", a: "G20 Inchમાં Input અને G21 mmમાં Input માટે વપરાય છે." },
  { q: "G28 Codeનો ઉપયોગ શું છે?", a: "Machineને Reference અથવા Home Position પર મોકલવા માટે." },
  { q: "G40, G41 અને G42 શું દર્શાવે છે?", a: "G40 Compensation Cancel, G41 Compensation Left અને G42 Compensation Right દર્શાવે છે." },
  { q: "G50 Codeનો CNC Latheમાં ઉપયોગ શું છે?", a: "Maximum Spindle Speed અથવા Coordinate System Setting માટે વપરાય છે." },
  { q: "G54 Code શું છે?", a: "Workpiece Coordinate System 1 Select કરવા માટેનો Code છે." },
  { q: "G55 થી G59 Codesનો ઉપયોગ શેના માટે થાય છે?", a: "અલગ-અલગ Workpiece Coordinate Systems એટલે Work Offsets પસંદ કરવા માટે." },
  { q: "G70 અને G71નો ઉપયોગ શેના માટે થાય છે?", a: "G70 Finishing Cycle અને G71 Rough Turning અથવા Stock Removal Cycle માટે વપરાય છે." },
  { q: "G76 Codeનો ઉપયોગ શેના માટે થાય છે?", a: "CNC Latheમાં Multiple Threading Cycle માટે." },
  { q: "G80 Code શું કરે છે?", a: "Canned Cycleને Cancel કરે છે." },
  { q: "G81 અને G83નો ઉપયોગ શેના માટે થાય છે?", a: "G81 સામાન્ય Drilling Cycle અને G83 Peck Drilling/Deep Hole Drilling માટે વપરાય છે." },
  { q: "G84 Codeનો ઉપયોગ શું છે?", a: "Tapping Canned Cycle માટે." },
  { q: "G94, G96 અને G97 શું દર્શાવે છે?", a: "G94 End Face Turning Cycle, G96 Constant Surface Speed અને G97 Constant Surface Speed Cancel માટે વપરાય છે." },
  { q: "G98 અને G99નો ઉપયોગ શું છે?", a: "CNCમાં G98 Per Minute Feed અને G99 Per Revolution Feed માટે વપરાય છે." },
  { q: "M-Code શું છે?", a: "M-Code CNC મશીનના Auxiliary અથવા સહાયક Functions જેમ કે Spindle, Coolant અને Tool Changeને નિયંત્રિત કરે છે." },
  { q: "M00 અને M01માં શું તફાવત છે?", a: "M00 Program Stop કરે છે, જ્યારે M01 Optional Stop માટે વપરાય છે." },
  { q: "M03, M04 અને M05નો ઉપયોગ શેના માટે થાય છે?", a: "M03 Spindle Clockwise, M04 Spindle Counter-Clockwise અને M05 Spindle Stop માટે વપરાય છે." },
  { q: "M06, M08 અને M09નો ઉપયોગ શું છે?", a: "M06 Tool Change, M08 Coolant ON અને M09 Coolant OFF માટે વપરાય છે." },
  { q: "M10, M11, M13 અને M14નો ઉપયોગ શેના માટે થાય છે?", a: "M10 Tailstock Out, M11 Tailstock In, M13 Chuck Declamp અને M14 Chuck Clamp માટે વપરાય છે." },
  { q: "M30 અને M99નો ઉપયોગ શું છે?", a: "M30 Main Programનો અંત કરીને Program Reset કરે છે, જ્યારે M99 Subprogramનો અંત અથવા Unconditional Jump માટે વપરાય છે." }
]},
{ id: "c10-3", no: "10.3", title: "Block Search", qs: [
  { q: "Block Search શું છે?", a: "CNC મશીન Power Off થયા પછી અગાઉના ચોક્કસ Blockમાંથી Machining ફરી શરૂ કરવાની પ્રક્રિયાને Block Search કહે છે." },
  { q: "Block Searchની જરૂર ક્યારે પડે છે?", a: "Machining દરમિયાન Power Off અથવા Program Interruption થાય ત્યારે." },
  { q: "Power Off થયા પછી પ્રથમ શું કરવું?", a: "Power ફરી ON કરીને Machine Start કરવી." },
  { q: "Machineને Home Position પર શા માટે લઈ જવામાં આવે છે?", a: "Machineના Axisને Reference Position પર લાવવા માટે." },
  { q: "Home Position પર કયા ભાગોને લઈ જવામાં આવે છે?", a: "Machineના બધા જરૂરી Axisને એક-એક કરીને Home કરવામાં આવે છે." },
  { q: "Turretને Safe Position પર શા માટે રાખવામાં આવે છે?", a: "Tool અને Job વચ્ચે Collision ન થાય તે માટે." },
  { q: "Turret Index કરવાનો અર્થ શું છે?", a: "અગાઉ ઉપયોગમાં લેવાયેલ Toolને ફરીથી યોગ્ય Tool Position પર Select કરવાની પ્રક્રિયા." },
  { q: "Block Search પહેલાં કયો Mode Select કરવામાં આવે છે?", a: "Auto અથવા Memory Mode Select કરવામાં આવે છે." },
  { q: "Block Number શું છે?", a: "CNC Programમાં દરેક Program Blockને ઓળખવા માટે આપવામાં આવતો Number છે." },
  { q: "Block Numberનું ઉદાહરણ આપો.", a: "N0010, N0020, N0030 વગેરે." },
  { q: "Program Numberનું ઉદાહરણ શું છે?", a: "O0001." },
  { q: "Power Off પહેલાં કયા Block પર Machine ચાલી રહી હતી તે શા માટે શોધવું પડે?", a: "Machining યોગ્ય જગ્યાએથી ફરી શરૂ કરવા માટે." },
  { q: "Block Searchમાં Cursorનો ઉપયોગ શા માટે થાય છે?", a: "જરૂરી Block Number શોધવા અને Select કરવા માટે." },
  { q: "Block Searchમાં Cursor Down Keyનો ઉપયોગ શું છે?", a: "જ્યાંથી Machining ફરી શરૂ કરવી હોય તે Block પર Cursor લઈ જવા માટે." },
  { q: "Block Select કર્યા પછી કઈ Key દબાવવામાં આવે છે?", a: "Cycle Start Key." },
  { q: "Cycle Start દબાવ્યા પછી શું થાય છે?", a: "Machine પસંદ કરેલા Blockથી Machining ફરી શરૂ કરે છે." },
  { q: "Block Searchનો મુખ્ય હેતુ શું છે?", a: "આખો Program ફરીથી ચલાવ્યા વગર જરૂરી Blockથી Machining શરૂ કરવી." },
  { q: "Block Search પહેલાં Tool Position કેમ ચકાસવી જોઈએ?", a: "Tool અને Workpiece વચ્ચે Collision ટાળવા માટે." },
  { q: "Dry Run શું છે?", a: "Actual Cutting પહેલાં Program અથવા Tool Movementને ચકાસવાની પ્રક્રિયા Dry Run કહેવાય છે." },
  { q: "Block Search પહેલાં Dry Run શા માટે ઉપયોગી છે?", a: "Tool Movement અને Programમાં ભૂલ અથવા Collisionનું જોખમ ઘટાડવા માટે." },
  { q: "CNC Programમાં Remark લખવાનો શું ફાયદો છે?", a: "જરૂરી Operation અથવા Blockને ઝડપથી ઓળખવામાં મદદ મળે છે." },
  { q: "Block Searchમાં Safe Positionનો શું અર્થ છે?", a: "Tool અથવા Turretને Jobથી સુરક્ષિત અંતરે રાખેલી Position." },
  { q: "Block Searchની સામાન્ય પ્રક્રિયા કઈ છે?", a: "Power ON → Home Position → Turret Safe Position → Tool Index → Auto/Memory Mode → Block Search → Cycle Start." },
  { q: "Block Searchમાં Tool ફરીથી Select કરવું શા માટે જરૂરી છે?", a: "યોગ્ય Toolથી Machining ફરી શરૂ થાય તે માટે." },
  { q: "Block Search કરતી વખતે મુખ્ય સાવચેતી કઈ રાખવી જોઈએ?", a: "Correct Tool, Offset, Work Coordinate, Block Number અને Safe Position ચકાસ્યા પછી જ Cycle Start કરવું." }
]},
{ id: "c10-4", no: "10.4", title: "CNC Offset", qs: [
  { q: "CNC Offset શું છે?", a: "CNC મશીનમાં Tool અથવા Workpieceની ચોક્કસ Position નક્કી કરવા માટે ઉપયોગમાં લેવાતા ડેટાને Offset કહે છે." },
  { q: "CNC Latheમાં મુખ્ય Offset કયા છે?", a: "Geometry Offset, Wear Offset અને Work Shift Offset." },
  { q: "Geometry Offset શું છે?", a: "દરેક Tool માટે X અને Z Axisની Position Set કરવા માટે લેવાતો Offset Geometry Offset કહેવાય છે." },
  { q: "Geometry Offset ક્યારે લેવામાં આવે છે?", a: "Job machining શરૂ કરતા પહેલાં Tool Set કરતી વખતે." },
  { q: "Geometry Offsetમાં કયા Axisના Offset લેવામાં આવે છે?", a: "CNC Latheમાં X-Axis અને Z-Axisના Offset લેવામાં આવે છે." },
  { q: "Wear Offset શું છે?", a: "Tool ઘસાઈ જવાથી Dimensionમાં આવતો ફેરફાર સુધારવા માટે ઉપયોગમાં લેવાતો Offset Wear Offset કહેવાય છે." },
  { q: "Wear Offset કયા Unitમાં સામાન્ય રીતે દાખલ કરવામાં આવે છે?", a: "સામાન્ય રીતે Micronમાં દાખલ કરવામાં આવે છે." },
  { q: "Tool Wear થવાથી શું અસર થાય છે?", a: "Jobની Dimension ખોટી આવી શકે છે." },
  { q: "Work Shift Offset શું છે?", a: "Geometry Offsetને Plus અથવા Minus દિશામાં Shift કરવા માટે Work Shift Offsetનો ઉપયોગ થાય છે." },
  { q: "Work Shift Offsetમાં કયા G-Codes વપરાય છે?", a: "G54, G55, G56, G57, G58 અને G59." },
  { q: "G54 થી G59 શું દર્શાવે છે?", a: "તે અલગ-અલગ Work Coordinate System અથવા Work Offset દર્શાવે છે." },
  { q: "Work Shift Offsetનો મુખ્ય ફાયદો શું છે?", a: "Machine માટે ચોક્કસ Working Point અથવા Work Zero Set કરી શકાય છે." },
  { q: "Z-Axis Geometry Offset લેતા પહેલાં શું કરવું?", a: "Machine ON કરીને Zero Return અથવા Homing કરવું." },
  { q: "Jobને CNC Latheમાં ક્યાં પકડવામાં આવે છે?", a: "Chuckમાં." },
  { q: "Toolને Jobની Faceથી શરૂઆતમાં કેટલા અંતરે રાખવામાં આવે છે?", a: "આશરે 2–3 mm દૂર રાખવામાં આવે છે." },
  { q: "Fine Tool Movement માટે કેટલો Step ઉપયોગી છે?", a: "10 Micron એટલે કે 0.01 mm Step." },
  { q: "Z-Axis Offset લેવા માટે Paper Method શું છે?", a: "Job અને Tool વચ્ચે Paper રાખીને Toolને ધીમે ધીમે આગળ લાવવામાં આવે છે અને Paper ફસાઈ જાય ત્યારે Position Set કરવામાં આવે છે." },
  { q: "Z-Axis Geometry Offsetમાં કઈ Value દાખલ કરવામાં આવે છે?", a: "Z = 0.0 દાખલ કરીને MEASURE કરવામાં આવે છે." },
  { q: "X-Axis Geometry Offset માટે Jobનું શું માપ જરૂરી છે?", a: "Jobનું બહારનું Diameter (OD) જરૂરી છે." },
  { q: "જો Jobનું OD 20 mm હોય તો X Geometry Offsetમાં શું દાખલ કરશો?", a: "X = 20.0 દાખલ કરીને MEASURE કરશો." },
  { q: "VMCમાં મુખ્ય Work Offset Axis કયા છે?", a: "X, Y અને Z Axis." },
  { q: "VMCમાં Tool Length Offset કયા નામથી ઓળખાય છે?", a: "H Offset." },
  { q: "VMCમાં Tool Radius Offset કયા નામથી ઓળખાય છે?", a: "D Offset." },
  { q: "VMCમાં G54 Z-Zero કેવી રીતે Set કરવામાં આવે છે?", a: "Toolને Jobની ઉપરની Surface પર Paper Methodથી Touch કરાવી, Work Offsetમાં G54ના Z Columnમાં Z = 0.0 દાખલ કરીને MEASURE કરવામાં આવે છે." },
  { q: "VMCમાં Center Offset કેવી રીતે મેળવવામાં આવે છે?", a: "Jobની બંને બાજુ Touch કરીને બંને Valuesનો Difference કાઢી તેનો અડધો કરીને Toolને Center પર લાવવામાં આવે છે અને પછી G54માં X અથવા Y = 0.0 MEASURE કરવામાં આવે છે." }
]},
{ id: "c10-5", no: "10.5", title: "G-Code Cycle", qs: [
  { q: "G32 શું છે?", a: "G32 એ Thread Cutting Cycle છે, જે CNC Latheમાં Thread બનાવવા માટે વપરાય છે." },
  { q: "G32માં X, Z અને F શું દર્શાવે છે?", a: "X = Diameter, Z = Thread Length અને F = Thread Lead/Pitch." },
  { q: "G71 શું છે?", a: "G71 Multiple Turning અથવા Rough Turning Cycle છે. તેનો ઉપયોગ વધારાનું Material દૂર કરવા માટે થાય છે." },
  { q: "G71માં U શું દર્શાવે છે?", a: "U દરેક Roughing Pass માટેની Depth of Cut દર્શાવે છે." },
  { q: "G71માં P અને Q શું દર્શાવે છે?", a: "P = પ્રથમ Block Number અને Q = અંતિમ Block Number." },
  { q: "G71માં W શું દર્શાવે છે?", a: "W Length Directionમાં Finish Machining માટે રાખવામાં આવતું Allowance દર્શાવે છે." },
  { q: "G72 શું છે?", a: "G72 Multiple Facing અથવા Rough Facing Cycle છે." },
  { q: "G72નો મુખ્ય ઉપયોગ શું છે?", a: "Jobની Face પર વધારાનું Material Rough Facing દ્વારા દૂર કરવા માટે." },
  { q: "G73 શું છે?", a: "G73 Pattern Repeating Cycle છે, જે ચોક્કસ Pattern અથવા Profileને વારંવાર Machining કરવા માટે વપરાય છે." },
  { q: "G73માં R શું દર્શાવે છે?", a: "આપેલી પદ્ધતિ મુજબ R, U સાથે સંબંધિત Roughing Passની સંખ્યા/Pattern સંબંધિત Value દર્શાવે છે." },
  { q: "G74 શું છે?", a: "G74 Peck Drilling Cycle છે, જે CNC Latheમાં Deep Hole Drilling માટે વપરાય છે." },
  { q: "G74માં Q શું દર્શાવે છે?", a: "Q દરેક Peckમાં Tool કેટલી Depth સુધી Cutting કરશે તે દર્શાવે છે." },
  { q: "G75 શું છે?", a: "G75 Grooving Cycle છે, જે CNC Latheમાં Groove બનાવવા માટે વપરાય છે." },
  { q: "G75માં P અને Q શું દર્શાવે છે?", a: "P = X-Axisમાં Depth of Cut Increment અને Q = Z-Axisમાં Cutting Increment દર્શાવે છે." },
  { q: "G76 શું છે?", a: "G76 Multiple Threading Cycle છે, જે CNC Latheમાં ચોક્કસ Thread Cutting માટે વપરાય છે." },
  { q: "G76માં F શું દર્શાવે છે?", a: "F Threadની Lead અથવા Pitch દર્શાવે છે." },
  { q: "G83 શું છે?", a: "G83 Drilling Cycle અથવા Peck Drilling Cycle છે, જે Deep Hole Drilling માટે વપરાય છે." },
  { q: "G83માં Z, Q, R અને F શું દર્શાવે છે?", a: "Z = કુલ Drilling Depth, Q = Peck Depth, R = Retract Plane અને F = Feed." },
  { q: "G90 શું છે?", a: "આપેલી નોંધ મુજબ G90 Single Turning Cycle છે, જે Straight Turning માટે વપરાય છે." },
  { q: "G91 શું છે?", a: "આપેલી નોંધ મુજબ G91 Single Turning Cycle છે, જે Taper Turning માટે વપરાય છે." },
  { q: "G92 શું છે?", a: "G92 Single Threading Cycle છે, જે CNC Latheમાં Thread Cutting માટે વપરાય છે." },
  { q: "G70 શું છે?", a: "G70 Finishing Cycle છે, જે Rough Turning પછી Final Finishing માટે વપરાય છે." },
  { q: "G70માં P અને Q શું દર્શાવે છે?", a: "P = Finishing Profileનો પ્રથમ Block અને Q = Finishing Profileનો છેલ્લો Block." },
  { q: "G70 કયા Roughing Cycle પછી ઉપયોગી છે?", a: "G71, G72 અથવા G73 દ્વારા Rough Machining કર્યા પછી G70 Finishing Cycle વપરાય છે." },
  { q: "G-Code Cycleમાં Unitનું ધ્યાન રાખવું શા માટે જરૂરી છે?", a: "Q અને P જેવી Values ઘણી વખત Micronમાં હોય છે, જ્યારે U, W, R અને F જેવી Values mmમાં હોઈ શકે છે. તેથી યોગ્ય Unit રાખવી જરૂરી છે." }
]},
{ id: "c10-6", no: "10.6", title: "RPM, Cutting Speed અને Feed Rate (Formulas)", qs: [
  { q: "RPM નું પૂરું નામ શું છે?", a: "Revolution Per Minute." },
  { q: "RPM શું દર્શાવે છે?", a: "એક મિનિટમાં સ્પિન્ડલ અથવા વર્કપીસ કેટલા ચક્કર ફરે તે RPM દર્શાવે છે." },
  { q: "RPM નું સૂત્ર શું છે?", a: "RPM = (1000 × V) / (π × D)" },
  { q: "RPM ના સૂત્રમાં V શું દર્શાવે છે?", a: "V એટલે Cutting Speed (m/min)." },
  { q: "RPM ના સૂત્રમાં D શું દર્શાવે છે?", a: "D એટલે Workpiece Diameter (mm)." },
  { q: "π (પાઈ) ની કિંમત કેટલી લેવામાં આવે છે?", a: "સામાન્ય ગણતરીમાં π = 3.14 લેવામાં આવે છે." },
  { q: "Cutting Speed નું એકમ શું છે?", a: "મીટર પ્રતિ મિનિટ (m/min)." },
  { q: "Cutting Speed શું છે?", a: "ટૂલ વર્કપીસની સપાટી પર જે ઝડપે કટ કરે તેને Cutting Speed કહે છે." },
  { q: "Cutting Speed નું સૂત્ર શું છે?", a: "V = (π × D × N) / 1000" },
  { q: "Cutting Speed વધારવા માટે શું કરી શકાય?", a: "RPM વધારી શકાય અથવા જોબ/કટરનો વ્યાસ વધારી શકાય." },
  { q: "જો Cutting Speed વધે તો RPM પર શું અસર થાય છે?", a: "વ્યાસ સમાન હોય તો RPM વધે છે." },
  { q: "જો Workpiece Diameter વધે તો RPM પર શું અસર થાય છે?", a: "Cutting Speed સમાન હોય તો RPM ઘટે છે." },
  { q: "Cutting Feed શું છે?", a: "કટિંગ દરમિયાન ટૂલ અથવા વર્કપીસ એક રેવોલ્યુશન અથવા એક મિનિટમાં જેટલું આગળ વધે તે Cutting Feed છે." },
  { q: "Turning માં Feed નું સામાન્ય એકમ શું છે?", a: "mm/rev." },
  { q: "Milling માં Feed નું એકમ શું છે?", a: "mm/tooth." },
  { q: "Feed Rate નું એકમ શું છે?", a: "mm/min." },
  { q: "Feed વધારવાથી Material Removal Rate પર શું અસર થાય છે?", a: "Material Removal Rate વધે છે." },
  { q: "Feed વધારવાથી Surface Finish પર શું અસર થાય છે?", a: "સામાન્ય રીતે Surface Finish ખરાબ થાય છે." },
  { q: "Feed ઓછો રાખવાથી શું ફાયદો થાય છે?", a: "સામાન્ય રીતે Surface Finish સારી મળે છે." },
  { q: "Cycle Time શું છે?", a: "મશીનિંગ પ્રક્રિયા પૂર્ણ કરવામાં લાગતો કુલ સમય Cycle Time કહેવાય છે." },
  { q: "Machining Time નું સૂત્ર શું છે?", a: "Machining Time = (Machining Length × Number of Passes) / Feed Rate" },
  { q: "Machining Length એટલે શું?", a: "ટૂલ જેટલી લંબાઈ સુધી મશીનિંગ કરે તે Machining Length છે." },
  { q: "જો Machining Length 80 mm, Feed Rate 200 mm/min અને 2 Pass હોય તો Cycle Time કેટલો?", a: "Cycle Time = (80 × 2) / 200 = 0.8 મિનિટ = 48 સેકન્ડ." },
  { q: "CNC મશીનમાં Hydraulic Oil નો ઉપયોગ ક્યાં થાય છે?", a: "Hydraulic System, Hydraulic Cylinder, Pump, Valve વગેરેમાં થાય છે." },
  { q: "Hydraulic Oil ના સામાન્ય ISO VG ગ્રેડ કયા છે?", a: "ISO VG 32, ISO VG 46 અને ISO VG 68." }
]},
{ id: "c10-7", no: "10.7", title: "CNC Display Value, Cutting Oil / Coolant અને GD&T", qs: [
  { q: "Machine Value શું દર્શાવે છે?", a: "Machine Value મશીનના Original Zero અથવા Home Positionથી tool નું distance દર્શાવે છે." },
  { q: "Machine Zero કેવી રીતે નક્કી થાય છે?", a: "મશીનને Reference/Home કરવાથી Machine Zero નક્કી થાય છે." },
  { q: "Machine Value operator બદલી શકે છે?", a: "સામાન્ય રીતે નહીં, તે મશીનનું internal reference છે." },
  { q: "Absolute Value શું દર્શાવે છે?", a: "Absolute Value Work Zero, જેમ કે G54, પરથી tool નું distance દર્શાવે છે." },
  { q: "જો Job Zero face પર હોય અને tool 20 mm અંદર હોય તો Absolute Z કેટલું બતાવી શકે?", a: "Z = -20 mm." },
  { q: "Relative Value શું છે?", a: "Operator પોતાની જરૂરિયાત મુજબ કોઈપણ point ને temporary Zero બનાવી શકે તે Relative Value છે." },
  { q: "Relative Zero કોણ સેટ કરી શકે?", a: "Operator." },
  { q: "Distance To Go શું દર્શાવે છે?", a: "Command આપ્યા પછી tool ને હજુ કેટલું distance જવાનું બાકી છે તે દર્શાવે છે." },
  { q: "Tool X40 પર છે અને command X100 છે, તો Distance To Go કેટલું?", a: "60 mm." },
  { q: "Tool આગળ વધે તેમ Distance To Go પર શું અસર થાય છે?", a: "Tool આગળ વધે તેમ Distance To Go ની value ઘટતી જાય છે." },
  { q: "Cutting Oil/Coolant નો મુખ્ય ઉપયોગ શું છે?", a: "Cutting દરમિયાન ઘર્ષણ અને ગરમી ઘટાડવા તથા tool life વધારવા માટે." },
  { q: "Soluble Cutting Oil શું છે?", a: "પાણીમાં મિશ્રણ કરીને વપરાતું cutting fluid છે." },
  { q: "Straight Cutting Oil શું છે?", a: "જે cutting oil સીધું વપરાય છે તેને Straight Cutting Oil કહે છે." },
  { q: "Coolant વાપરવાથી Tool Life પર શું અસર થાય છે?", a: "યોગ્ય coolant વાપરવાથી Tool Life વધે છે." },
  { q: "Lubrication Oil નો ઉપયોગ ક્યાં થાય છે?", a: "Spindle, gears, bearings અને moving parts ના ઘસારા ઘટાડવા માટે થાય છે." },
  { q: "Lubrication Oil ના સામાન્ય ISO VG ગ્રેડ કયા છે?", a: "ISO VG 32, 46 અને 68." },
  { q: "મશીનના oil reservoir ને સ્વચ્છ રાખવું કેમ જરૂરી છે?", a: "ગંદકી અને contaminationને કારણે machine parts ને નુકસાન ન થાય તે માટે." },
  { q: "Straightness નો અર્થ શું છે?", a: "કોઈ line અથવા surface સીધી હોવાની geometric condition ને Straightness કહે છે." },
  { q: "Flatness શું દર્શાવે છે?", a: "કોઈ surface કેટલું સમતલ છે તે Flatness દર્શાવે છે." },
  { q: "Circularity શું છે?", a: "કોઈ circular feature નો દરેક cross-section યોગ્ય circular formમાં કેટલો છે તે Circularity દર્શાવે છે." },
  { q: "Perpendicularity નો અર્થ શું છે?", a: "કોઈ feature અથવા surface datum સામે 90° પર હોવાની tolerance ને Perpendicularity કહે છે." },
  { q: "Parallelism શું દર્શાવે છે?", a: "બે surfaces અથવા features એકબીજાને parallel હોવાની geometric condition છે." },
  { q: "Position symbol શું દર્શાવે છે?", a: "કોઈ feature, જેમ કે hole, ની ચોક્કસ positional location માટેની tolerance દર્શાવે છે." },
  { q: "MMC અને LMC નું પૂરું નામ શું છે?", a: "MMC = Maximum Material Condition અને LMC = Least Material Condition." },
  { q: "Diameter અને Basic Dimension ના symbols કયા છે?", a: "Diameter = Ø અને Basic Dimension = theoretically exact dimension, જે drawingમાં સામાન્ય રીતે boxમાં દર્શાવવામાં આવે છે." }
]},
{ id: "c12-0", no: "12.0", title: "ઇન્ટરવ્યૂના મહત્વના પ્રશ્નો (Important Interview Questions)", qs: [
  { q: "Tell me about yourself.", a: "મારું નામ ___ છે. મેં ___ સુધી અભ્યાસ કર્યો છે. મને CNC/Machining ક્ષેત્રમાં રસ છે અને મને ___ વર્ષનો અનુભવ છે. હું મહેનતુ, ઈમાનદાર અને નવી વસ્તુઓ શીખવા માટે હંમેશા તૈયાર રહું છું." },
  { q: "Why do you want to work in our company?", a: "તમારી કંપની સારી પ્રતિષ્ઠા ધરાવે છે. મારી સ્કિલ્સ અને અભ્યાસ આ પોઝિશન માટે યોગ્ય છે અને અહીં મને શીખવાની તથા આગળ વધવાની સારી તક મળશે." },
  { q: "What are your strengths?", a: "મારી મુખ્ય Strengths મહેનત, ઈમાનદારી, સમયપાલન, Adaptability અને Positive Attitude છે." },
  { q: "What is your weakness?", a: "હું કામને ખૂબ ગંભીરતાથી લઉં છું અને ક્યારેક કામને સંપૂર્ણ રીતે કરવા માટે વધુ સમય આપું છું. હવે હું સમયનું વધુ સારું આયોજન શીખી રહ્યો છું." },
  { q: "Why should I hire you?", a: "મારી પાસે જરૂરી technical knowledge, શીખવાની ઈચ્છા અને જવાબદારીપૂર્વક કામ કરવાની ક્ષમતા છે. મને તક મળશે તો કંપનીના ઉત્પાદન અને qualityમાં સારો ફાળો આપીશ." },
  { q: "What do you know about our company?", a: "તમારી કંપનીના products, quality અને growth વિશે મેં માહિતી મેળવી છે. કંપનીની reputation સારી છે અને અહીં career growthની સારી તક છે." },
  { q: "Why are you looking for a job change?", a: "હું નવી જવાબદારી લેવા, નવી technology શીખવા અને મારી career growth માટે સારી તક શોધી રહ્યો છું." },
  { q: "What are your salary expectations?", a: "કંપનીના નિયમો અને position પ્રમાણે યોગ્ય salary મને સ્વીકાર્ય છે. મારી skill અને experience પ્રમાણે યોગ્ય packageની અપેક્ષા છે." },
  { q: "Are you a fresher or experienced?", a: "હું Fresher/Experienced છું. મને CNC machining અને સંબંધિત કામમાં રસ છે અને હું મારી skillને વધુ વિકસાવવા માંગું છું." },
  { q: "What is CNC?", a: "CNC એટલે Computer Numerical Control. Computer program દ્વારા machine tool ને control કરવાની પદ્ધતિને CNC કહે છે." },
  { q: "What is RPM?", a: "RPM એટલે Revolution Per Minute, એટલે spindle અથવા workpiece એક મિનિટમાં કેટલા ચક્કર ફરે." },
  { q: "What is Cutting Speed?", a: "Tool અને workpiece વચ્ચે cutting દરમિયાન સપાટી પર થતી cuttingની ઝડપને Cutting Speed કહે છે. તેનું એકમ m/min છે." },
  { q: "What is Feed Rate?", a: "Cutting દરમિયાન tool એક મિનિટમાં જેટલું અંતર આગળ વધે તેને Feed Rate કહે છે. તેનું એકમ સામાન્ય રીતે mm/min છે." },
  { q: "What is Feed in Turning?", a: "Turningમાં એક spindle revolution દરમિયાન tool જેટલું આગળ વધે તેને Feed કહે છે. તેનું એકમ mm/rev છે." },
  { q: "What is Coolant?", a: "Machining દરમિયાન cutting zoneની ગરમી અને ઘર્ષણ ઘટાડવા માટે વપરાતા fluidને Coolant કહે છે." },
  { q: "Why is coolant used in CNC machining?", a: "Tool અને workpieceનું temperature ઘટાડવા, tool life વધારવા અને સારી surface finish મેળવવા માટે coolant વપરાય છે." },
  { q: "What is Machine Zero?", a: "Machineનું મૂળ અથવા Home/Reference position પરથી નક્કી થતું zero point Machine Zero કહેવાય છે." },
  { q: "What is Work Zero?", a: "Job પર operator દ્વારા નક્કી કરવામાં આવેલ zero pointને Work Zero કહે છે. CNCમાં G54 જેવા work offsetનો ઉપયોગ થાય છે." },
  { q: "What is Absolute Value?", a: "Work Zeroથી toolનું current position distance Absolute Valueમાં દર્શાવવામાં આવે છે." },
  { q: "What is Relative Value?", a: "Operator પોતાની જરૂરિયાત મુજબ કોઈપણ pointને temporary zero બનાવીને જે distance માપે તેને Relative Value કહે છે." },
  { q: "What is Distance To Go?", a: "આપેલા command મુજબ toolને હજુ જેટલું distance move કરવાનું બાકી હોય તેને Distance To Go કહે છે." },
  { q: "What is G54?", a: "G54 એક Work Coordinate System/Work Offset છે, જેના દ્વારા jobનું work zero સેટ કરવામાં આવે છે." },
  { q: "What is preventive maintenance?", a: "Machineમાં fault થાય તે પહેલાં oil, coolant, lubrication, cleaning અને અન્ય જરૂરી checks નિયમિત રીતે કરવા તેને Preventive Maintenance કહે છે." },
  { q: "Can you work under pressure?", a: "હા, હું pressureમાં પણ શાંતિથી અને safety તથા qualityનું ધ્યાન રાખીને કામ કરી શકું છું." },
  { q: "Where do you see yourself in five years?", a: "આગામી પાંચ વર્ષમાં હું મારી technical skills અને CNC knowledgeમાં નિષ્ણાત બનવા, વધુ જવાબદારી લેવા અને કંપનીની growthમાં મહત્વનો ફાળો આપવા ઈચ્છું છું." }
]}
]);
